INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tJV0aNwRWX3', 4, '{"title":"第20300220条・经别第十一","description":"<p>2、足太阳之正。别入于腘中。其一道下尻五寸。别入于肛。属于膀胱。散之肾。循膂。当心入散。直者。从膂上出于项。复属于太阳。此为一经也。足少阴之正。至腘中。别走太阳而合。上至肾。当十四椎出属带脉。直者。系舌本。复出于项。合于太阳。此为一合。成以诸阴之别。皆为正也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300220,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、足太阳之正。别入于腘中。其一道下尻五寸。别入于肛。属于膀胱。散之肾。循膂。当心入散。直者。从膂上出于项。复属于太阳。此为一经也。足少阴之正。至腘中。别走太阳而合。上至肾。当十四椎出属带脉。直者。系舌本。复出于项。合于太阳。此为一合。成以诸阴之别。皆为正也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'WyHv50K4GIu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f6FNPppIISR', 4, '{"title":"第20300221条・经别第十一","description":"<p>3、足少阳之正。绕髀入毛际。合于厥阴。别者入季胁之间。循胸里属胆。散之上肝。贯心以上挟咽。出颐颌中。散于面。系目系。合少阳于外眦也。足厥阴之正。别跗上。上至毛际。合于少阳。与别俱行。此为二合也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300221,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、足少阳之正。绕髀入毛际。合于厥阴。别者入季胁之间。循胸里属胆。散之上肝。贯心以上挟咽。出颐颌中。散于面。系目系。合少阳于外眦也。足厥阴之正。别跗上。上至毛际。合于少阳。与别俱行。此为二合也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'WyHv50K4GIu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GyWz4q3x4ne', 4, '{"title":"第20300222条・经别第十一","description":"<p>4、足阳明之正。上至脾。入于腹里属胃。散之脾。上通于心。上循咽出于口。上頞䪼。还系目系。合于阳明也。足太阴之正。上至髀。合于阳明。与别俱行。上结于咽。贯舌中。此为三合也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300222,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、足阳明之正。上至脾。入于腹里属胃。散之脾。上通于心。上循咽出于口。上頞䪼。还系目系。合于阳明也。足太阴之正。上至髀。合于阳明。与别俱行。上结于咽。贯舌中。此为三合也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'WyHv50K4GIu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AKA4VSo282o', 4, '{"title":"第20300223条・经别第十一","description":"<p>5、手太阳之正。指地。别于肩解。入腋走心。系小肠也。手少阴之正。别入于渊腋两筋之间。属于心。上走喉咙。出于面。合目内眦。此为四合也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300223,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、手太阳之正。指地。别于肩解。入腋走心。系小肠也。手少阴之正。别入于渊腋两筋之间。属于心。上走喉咙。出于面。合目内眦。此为四合也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'WyHv50K4GIu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a7FVhDjW5Sp', 4, '{"title":"第20300224条・经别第十一","description":"<p>6、手少阳之正。指天。别于巅。入缺盆。下走三焦。散于胸中也。手心主之正。别下渊腋三寸。入胸中。别属三焦。出循喉咙。出耳后。合少阳完骨之下。此为五合也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300224,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '6、手少阳之正。指天。别于巅。入缺盆。下走三焦。散于胸中也。手心主之正。别下渊腋三寸。入胸中。别属三焦。出循喉咙。出耳后。合少阳完骨之下。此为五合也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'WyHv50K4GIu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xwrqyTw9af2', 4, '{"title":"第20300225条・经别第十一","description":"<p>7、手阳明之正。从手循膺乳。别于肩髃。入柱骨。下走大肠。属于肺。上循喉咙。出缺盆。合于阳明也。手太阴之正。别入渊腋少阴之前。入走肺。散之大阳$a{肠}。上出缺盆。循喉咙。复合阳明。此六合也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300225,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '7、手阳明之正。从手循膺乳。别于肩髃。入柱骨。下走大肠。属于肺。上循喉咙。出缺盆。合于阳明也。手太阴之正。别入渊腋少阴之前。入走肺。散之大阳$a{肠}。上出缺盆。循喉咙。复合阳明。此六合也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'WyHv50K4GIu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c20CdR8bQJ6', 4, '{"title":"第20300226条・经水第十二","description":"<p>1、黄帝问于岐伯曰。经脉十二者。外合于十二经水。而内属于五藏六府。夫十二经水者。其有大小。深浅。广狭。远近各不同。五藏六府之高下。大小。受谷之多少亦不等。相应奈何。夫经水者。受水而行之。五藏者。合神气魂魄而藏之。六府者。受谷而行之。受气而扬之。经脉者。受血而营之。合而以治。奈何。刺之深浅。灸之壮数。可得闻乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300226,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝问于岐伯曰。经脉十二者。外合于十二经水。而内属于五藏六府。夫十二经水者。其有大小。深浅。广狭。远近各不同。五藏六府之高下。大小。受谷之多少亦不等。相应奈何。夫经水者。受水而行之。五藏者。合神气魂魄而藏之。六府者。受谷而行之。受气而扬之。经脉者。受血而营之。合而以治。奈何。刺之深浅。灸之壮数。可得闻乎。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cVDH1q1S5Xl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0eeDB1yu5s9', 4, '{"title":"第20300227条・经水第十二","description":"<p>2、岐伯答曰。善哉问也。天至高不可度。地至广不可量。此之谓也。且夫人生于天地之间。六合之内。此天之高。地之广也。非人力之所能度量而至也。若夫八尺之士。皮肉在此。外可度量切循而得之。其死可解剖而视之。其藏之坚脆。府之大小。谷之多少。脉之长短。血之清浊。气之多少。十二经之多血少气。与其少血多气。与其皆多血气。与其皆少血气。皆有大数。其治以针艾。各调其经气。固其常有合乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300227,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、岐伯答曰。善哉问也。天至高不可度。地至广不可量。此之谓也。且夫人生于天地之间。六合之内。此天之高。地之广也。非人力之所能度量而至也。若夫八尺之士。皮肉在此。外可度量切循而得之。其死可解剖而视之。其藏之坚脆。府之大小。谷之多少。脉之长短。血之清浊。气之多少。十二经之多血少气。与其少血多气。与其皆多血气。与其皆少血气。皆有大数。其治以针艾。各调其经气。固其常有合乎。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cVDH1q1S5Xl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AUBZlVWs6mG', 4, '{"title":"第20300228条・经水第十二","description":"<p>3、黄帝曰。余闻之。快于耳不解于心。愿卒闻之。岐伯答曰。此人之所以参天地而应阴阳也。不可不察。足太阳外合清水。内属于膀胱。而通水道焉。足少阳外合于渭水。内属于胆。足阳明外合于海水。内属于胃。足太阴外合于湖水。内属于脾。足少阴外合于汝水。内属于肾。足厥阴外合于渑水。内属于肝。手太阳外合于淮水。内属于小肠。而水道出焉。手少阳外合于漯水。内属于三焦。手阳明外合于江水。内属于大肠。手太阴外合于河水。内属于肺。手少阴外合济水。内属于心。手心主外合于漳水。内属于心包。凡此五藏六府十二经水者。外有源泉。而内有所禀。此皆内外相贯。如环无端。人经亦然。故天为阳。地为阴。腰以上为天。腰以下为地。故海以北者为阴。湖以北者为阴中之阴。漳以南者为阳。河以北至漳者为阳中之阴。漯以南至江者。为阳中之太阳。此一隅之阴阳也。所以人与天地相参也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300228,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、黄帝曰。余闻之。快于耳不解于心。愿卒闻之。岐伯答曰。此人之所以参天地而应阴阳也。不可不察。足太阳外合清水。内属于膀胱。而通水道焉。足少阳外合于渭水。内属于胆。足阳明外合于海水。内属于胃。足太阴外合于湖水。内属于脾。足少阴外合于汝水。内属于肾。足厥阴外合于渑水。内属于肝。手太阳外合于淮水。内属于小肠。而水道出焉。手少阳外合于漯水。内属于三焦。手阳明外合于江水。内属于大肠。手太阴外合于河水。内属于肺。手少阴外合济水。内属于心。手心主外合于漳水。内属于心包。凡此五藏六府十二经水者。外有源泉。而内有所禀。此皆内外相贯。如环无端。人经亦然。故天为阳。地为阴。腰以上为天。腰以下为地。故海以北者为阴。湖以北者为阴中之阴。漳以南者为阳。河以北至漳者为阳中之阴。漯以南至江者。为阳中之太阳。此一隅之阴阳也。所以人与天地相参也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cVDH1q1S5Xl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('j5NQBLYIUUB', 4, '{"title":"第20300229条・经水第十二","description":"<p>4、黄帝曰。夫经水之应经脉也。其远近浅深。水血之多少。各不同。合而以刺之奈何。岐伯答曰。足阳明。五藏六府之海也。其脉大。血多气盛。热壮。刺此者不深勿散。不留不泻也。足阳明刺深六分。留十呼。足太阳深五分。留七呼。足少阳深四分。留五呼。足太阴深三分。留四呼。足少阴深二分。留三呼。足厥阴深一分。留二呼。手之阴阳。其受气之道近。其气之来疾。其刺深者。皆无过二分。其留。皆无过一呼。其少长。大小。肥瘦。以心擦之。命曰法天之常。灸之亦然。灸而过此者。得恶火则骨枯脉涩。刺而过此者。则脱气。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300229,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、黄帝曰。夫经水之应经脉也。其远近浅深。水血之多少。各不同。合而以刺之奈何。岐伯答曰。足阳明。五藏六府之海也。其脉大。血多气盛。热壮。刺此者不深勿散。不留不泻也。足阳明刺深六分。留十呼。足太阳深五分。留七呼。足少阳深四分。留五呼。足太阴深三分。留四呼。足少阴深二分。留三呼。足厥阴深一分。留二呼。手之阴阳。其受气之道近。其气之来疾。其刺深者。皆无过二分。其留。皆无过一呼。其少长。大小。肥瘦。以心擦之。命曰法天之常。灸之亦然。灸而过此者。得恶火则骨枯脉涩。刺而过此者。则脱气。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cVDH1q1S5Xl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zHt7zi7JWFp', 4, '{"title":"第20300230条・经水第十二","description":"<p>5、黄帝曰。夫经脉之大小。血之多少。肤之厚薄。肉之坚脆及腘之大小。可为量度乎。岐伯答曰。其可为度量者。取其中度也。不甚脱肉。而血气不衰也。若夫度之人。消瘦而形肉脱者。恶可以度量刺乎。审。切。循。扪。按。视其寒温盛衰而调之。是谓因适而为之真也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300230,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、黄帝曰。夫经脉之大小。血之多少。肤之厚薄。肉之坚脆及腘之大小。可为量度乎。岐伯答曰。其可为度量者。取其中度也。不甚脱肉。而血气不衰也。若夫度之人。消瘦而形肉脱者。恶可以度量刺乎。审。切。循。扪。按。视其寒温盛衰而调之。是谓因适而为之真也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cVDH1q1S5Xl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('unw2EU4oOXf', 4, '{"title":"第20300231条・经筋第十三","description":"<p>1、足太阳之筋。起于足小指。上结于踝。邪上结于膝。其下循足外侧。结于踵。上循跟。结于腘。其别者。结于踹$a{腨}外。上腘中内廉。与腘中并上结于臀。上挟脊上项。其支者。别入结于舌本。其直者。结于枕骨。上头。下颜。结于鼻。其支者。为目上网。下结于頄。其支者。从腋后外廉结于肩髃。其支者。入腋下。上出缺盆。上结于完骨。其支者。出缺盆。邪上出于頄。其病小指支跟肿痛。腘挛。脊反折。项筋急。肩不举。腋支缺盆中纽痛。不可左右摇。治在燔针劫刺。以知为数。以痛为输。名曰仲春痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300231,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、足太阳之筋。起于足小指。上结于踝。邪上结于膝。其下循足外侧。结于踵。上循跟。结于腘。其别者。结于踹$a{腨}外。上腘中内廉。与腘中并上结于臀。上挟脊上项。其支者。别入结于舌本。其直者。结于枕骨。上头。下颜。结于鼻。其支者。为目上网。下结于頄。其支者。从腋后外廉结于肩髃。其支者。入腋下。上出缺盆。上结于完骨。其支者。出缺盆。邪上出于頄。其病小指支跟肿痛。腘挛。脊反折。项筋急。肩不举。腋支缺盆中纽痛。不可左右摇。治在燔针劫刺。以知为数。以痛为输。名曰仲春痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CgdWiCT5cg7', 4, '{"title":"第20300232条・经筋第十三","description":"<p>2、足少阳之筋。起于小指次指。上结外踝。上循胫外廉。结于膝外廉。其支者。别起外辅骨。上走髀。前者结于伏兔之上。后者。结于尻。其直者。上乘沙季胁。上走腋前廉。系于膺乳。结于缺盆。直者。上出腋。贯缺盆。出太阳之前。循耳后。上额角。交巅上。下走颔。上结于頄。支者。结于目眦为外维。其病小指次指支转筋。引膝外转筋。膝不可屈伸。腘筋急。前引髀。后引尻。即上乘䏚季胁痛。上引缺盆。膺乳。颈维筋急。从左之右。右目不开。上过右角。并蹻脉而行。左络于右。故伤左角。右足不用。命曰维筋相交。治在燔针劫刺。以知为数。以痛为输。名曰孟春痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300232,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、足少阳之筋。起于小指次指。上结外踝。上循胫外廉。结于膝外廉。其支者。别起外辅骨。上走髀。前者结于伏兔之上。后者。结于尻。其直者。上乘沙季胁。上走腋前廉。系于膺乳。结于缺盆。直者。上出腋。贯缺盆。出太阳之前。循耳后。上额角。交巅上。下走颔。上结于頄。支者。结于目眦为外维。其病小指次指支转筋。引膝外转筋。膝不可屈伸。腘筋急。前引髀。后引尻。即上乘䏚季胁痛。上引缺盆。膺乳。颈维筋急。从左之右。右目不开。上过右角。并蹻脉而行。左络于右。故伤左角。右足不用。命曰维筋相交。治在燔针劫刺。以知为数。以痛为输。名曰孟春痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D6SmaogFrz2', 4, '{"title":"第20300233条・经筋第十三","description":"<p>3、足阳明之筋。起于中三指。结于跗上。邪外上加于辅骨。上结于膝外廉。直上结于髀枢。上循胁属脊。其直者。上循骭。结于膝。其支者。结于外辅骨。合少阳。其直者。上循伏兔。上结于髀。聚于阴器。上腹而布。至缺盆而结。上颈。上挟口。合于頄。下结于鼻。上合于太阳。太阳为目上网。阳明为目下网。其支者。从颊结于耳前。其病足中指支胫转筋。脚跳坚。伏兔转筋。髀前踵。㿉疝。腹筋急。引缺盆及颊。卒口僻。急者。目不合。热则筋纵。目不开。颊筋有寒。则急。引颊移口。有热则筋弛纵。缓不胜收。故僻。治之以马膏。膏其急者。以白酒和桂。以涂其缓者。以桑钩钩之。即以生桑炭置之坎中。高下以坐等。以膏熨急颊。且饮美酒。敢美炙肉。不饮酒者。自强也。为之三拊而已。治在燔针劫刺。以知为数。以痛为输。名曰季春痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300233,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、足阳明之筋。起于中三指。结于跗上。邪外上加于辅骨。上结于膝外廉。直上结于髀枢。上循胁属脊。其直者。上循骭。结于膝。其支者。结于外辅骨。合少阳。其直者。上循伏兔。上结于髀。聚于阴器。上腹而布。至缺盆而结。上颈。上挟口。合于頄。下结于鼻。上合于太阳。太阳为目上网。阳明为目下网。其支者。从颊结于耳前。其病足中指支胫转筋。脚跳坚。伏兔转筋。髀前踵。㿉疝。腹筋急。引缺盆及颊。卒口僻。急者。目不合。热则筋纵。目不开。颊筋有寒。则急。引颊移口。有热则筋弛纵。缓不胜收。故僻。治之以马膏。膏其急者。以白酒和桂。以涂其缓者。以桑钩钩之。即以生桑炭置之坎中。高下以坐等。以膏熨急颊。且饮美酒。敢美炙肉。不饮酒者。自强也。为之三拊而已。治在燔针劫刺。以知为数。以痛为输。名曰季春痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M6cNg0UM13q', 4, '{"title":"第20300234条・经筋第十三","description":"<p>4、足太阴之筋。起于大指之端内侧。上结于内踝。其直者。络于膝内辅骨。上循阴股。结于髀。聚于阴器。上腹结于脐。循腹里。结于肋。散于胸中。其内者。着于脊。其病足大指支内踝痛。转筋痛。膝内辅骨痛。阴股引髀而痛。阴器纽痛。上引脐两胁痛。引膺中脊内痛。治在燔针劫刺。以知为数。以痛为输。命曰孟秋痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300234,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、足太阴之筋。起于大指之端内侧。上结于内踝。其直者。络于膝内辅骨。上循阴股。结于髀。聚于阴器。上腹结于脐。循腹里。结于肋。散于胸中。其内者。着于脊。其病足大指支内踝痛。转筋痛。膝内辅骨痛。阴股引髀而痛。阴器纽痛。上引脐两胁痛。引膺中脊内痛。治在燔针劫刺。以知为数。以痛为输。命曰孟秋痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hjcWvVjDInH', 4, '{"title":"第20300235条・经筋第十三","description":"<p>5、足少阴之筋。起于小指之下。并足太阴之筋。邪走内踝之下。结于踵。与太阳之筋合。而上结于内辅之下。并太阴之筋。而上循阴股。结于阴器。循脊内挟膂上至项。结于枕骨。与足太阳之筋合。其病足下转筋。及所过而结者皆痛及转筋。病在此者。主痫瘈及痉。在外者不能挽。在内者不能仰。故阳病者。腰反折不能俛。阴病者。不能仰。治在燔针劫刺。以知为数。以痛为输。在内者熨引饮药。此筋折纽。纽发数甚者死不治。名曰仲秋痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300235,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、足少阴之筋。起于小指之下。并足太阴之筋。邪走内踝之下。结于踵。与太阳之筋合。而上结于内辅之下。并太阴之筋。而上循阴股。结于阴器。循脊内挟膂上至项。结于枕骨。与足太阳之筋合。其病足下转筋。及所过而结者皆痛及转筋。病在此者。主痫瘈及痉。在外者不能挽。在内者不能仰。故阳病者。腰反折不能俛。阴病者。不能仰。治在燔针劫刺。以知为数。以痛为输。在内者熨引饮药。此筋折纽。纽发数甚者死不治。名曰仲秋痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pIcSSn0DPtA', 4, '{"title":"第20300236条・经筋第十三","description":"<p>6、足厥阴之筋。起于大指之上。上结于内踝之前。上循胫。上结内辅之下。上循阴股。结于阴器。络诸筋。其病足大指支内踝之前痛。内辅痛。阴股痛转筋。阴器不用。伤于内则不起。伤于寒则阴缩入。伤于热则纵挺不收。治在行水清阴气。其病转筋者。治在燔针劫刺。以知为数。以痛为输。命曰季秋痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300236,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '6、足厥阴之筋。起于大指之上。上结于内踝之前。上循胫。上结内辅之下。上循阴股。结于阴器。络诸筋。其病足大指支内踝之前痛。内辅痛。阴股痛转筋。阴器不用。伤于内则不起。伤于寒则阴缩入。伤于热则纵挺不收。治在行水清阴气。其病转筋者。治在燔针劫刺。以知为数。以痛为输。命曰季秋痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nfTWrHMYrMD', 4, '{"title":"第20300237条・经筋第十三","description":"<p>7、手太阳之筋。起于小指之上。结于腕。上循臂内廉。结于肘内锐骨之后。弹之应小指之上。入结于腋下。其支者。后走腋后廉。上绕肩胛。循颈出走太阳之前。结于耳后完骨。其支者。入耳中。直者。出耳上。下结于颔。上属目外眦。其病小指支肘内锐骨后廉痛。循臂阴。入腋下。腋下痛。腋后廉痛。绕肩胛引颈而痛。应耳中鸣痛引颔。目瞑良久乃得视。颈筋急。则为筋瘘颈肿。寒热在颈者。治在燔针劫刺之。以知为数。以痛为输。其为肿者。复而锐之。本支者。上曲牙。循耳前属目外眦。上颔结于角。其痛当所过者支转筋。治在燔针劫刺。以知为数。以痛为输。名曰仲夏痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300237,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '7、手太阳之筋。起于小指之上。结于腕。上循臂内廉。结于肘内锐骨之后。弹之应小指之上。入结于腋下。其支者。后走腋后廉。上绕肩胛。循颈出走太阳之前。结于耳后完骨。其支者。入耳中。直者。出耳上。下结于颔。上属目外眦。其病小指支肘内锐骨后廉痛。循臂阴。入腋下。腋下痛。腋后廉痛。绕肩胛引颈而痛。应耳中鸣痛引颔。目瞑良久乃得视。颈筋急。则为筋瘘颈肿。寒热在颈者。治在燔针劫刺之。以知为数。以痛为输。其为肿者。复而锐之。本支者。上曲牙。循耳前属目外眦。上颔结于角。其痛当所过者支转筋。治在燔针劫刺。以知为数。以痛为输。名曰仲夏痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aLDi0VwPIn4', 4, '{"title":"第20300238条・经筋第十三","description":"<p>8、手少阳之筋。起于小指次指之端。结于腕。中循臂。结于肘。上绕臑外廉。上肩。走颈。合手太阳。其支者。当曲颊入系舌本。其支者。上曲牙。循耳前。属目外眦。上乘颔。结于角。其病当所过者。即支转筋。舌卷。治在燔针劫刺。以知为数。以痛为输。名曰季夏痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300238,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '8、手少阳之筋。起于小指次指之端。结于腕。中循臂。结于肘。上绕臑外廉。上肩。走颈。合手太阳。其支者。当曲颊入系舌本。其支者。上曲牙。循耳前。属目外眦。上乘颔。结于角。其病当所过者。即支转筋。舌卷。治在燔针劫刺。以知为数。以痛为输。名曰季夏痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GsBHFAqb5Jy', 4, '{"title":"第20300239条・经筋第十三","description":"<p>9、手阳明之筋。起于大指次指之端。结于腕。上循臂。上结于肘外。上臑。结于髃。其支者。绕肩胛。挟脊。直者。从肩髃上颈。其支者。上颊。结于頄。直者。上出手太阳之前。上左角。络头。下右颔。其病当所过者。支痛及转筋。肩不举。颈不可左右视。治在燔针劫刺。以知为数。以痛为输。名曰孟夏痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300239,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '9、手阳明之筋。起于大指次指之端。结于腕。上循臂。上结于肘外。上臑。结于髃。其支者。绕肩胛。挟脊。直者。从肩髃上颈。其支者。上颊。结于頄。直者。上出手太阳之前。上左角。络头。下右颔。其病当所过者。支痛及转筋。肩不举。颈不可左右视。治在燔针劫刺。以知为数。以痛为输。名曰孟夏痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ImdblBl9cZp', 4, '{"title":"第20300240条・经筋第十三","description":"<p>10、手太阴之筋。起于大指之上。循指上行。结于鱼后。行寸口外侧。上循臂。结肘中。上臑内廉。入腋下。出缺盆。结肩前髃。上结缺盆。下结胸里。散贯贲。合贲下抵季胁。其病当所过者。支转筋。痛甚成息贲。胁急吐血。治在燔针劫刺。以知为数。以痛为输。名曰仲冬痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300240,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '10、手太阴之筋。起于大指之上。循指上行。结于鱼后。行寸口外侧。上循臂。结肘中。上臑内廉。入腋下。出缺盆。结肩前髃。上结缺盆。下结胸里。散贯贲。合贲下抵季胁。其病当所过者。支转筋。痛甚成息贲。胁急吐血。治在燔针劫刺。以知为数。以痛为输。名曰仲冬痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8SLbixGQtFS', 4, '{"title":"第20300241条・经筋第十三","description":"<p>11、手心主之筋。起于中指。与太阴之筋并行。结于肘内廉。上臂阴。结腋下。下散前后挟胁。其支者。入腋。散胸中。结于臂。其病当所过者。支转筋前及胸痛息贲。治在燔针劫刺。以知为数。以痛为输。名曰孟冬痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300241,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '11、手心主之筋。起于中指。与太阴之筋并行。结于肘内廉。上臂阴。结腋下。下散前后挟胁。其支者。入腋。散胸中。结于臂。其病当所过者。支转筋前及胸痛息贲。治在燔针劫刺。以知为数。以痛为输。名曰孟冬痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xX3ofwYVROs', 4, '{"title":"第20300242条・经筋第十三","description":"<p>12、手少阴之筋。起于小指之内侧。结于锐骨。上结肘内廉。上入腋。交太阴。挟乳里。结于胸中。循臂下系于脐。其病内急心承伏梁。下为肘网。其病当所过者。支转筋。筋痛。治在燔针劫刺。以知为数。以痛为输。其成伏梁唾血脓者。死不治。经筋之病。寒则反折筋急。热则筋弛纵不收。阴痿不用。阳急则反折。阴急则俛不伸。焠刺者。刺寒急也。热则筋纵不收。无用燔针。名曰季冬痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300242,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '12、手少阴之筋。起于小指之内侧。结于锐骨。上结肘内廉。上入腋。交太阴。挟乳里。结于胸中。循臂下系于脐。其病内急心承伏梁。下为肘网。其病当所过者。支转筋。筋痛。治在燔针劫刺。以知为数。以痛为输。其成伏梁唾血脓者。死不治。经筋之病。寒则反折筋急。热则筋弛纵不收。阴痿不用。阳急则反折。阴急则俛不伸。焠刺者。刺寒急也。热则筋纵不收。无用燔针。名曰季冬痹也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('USe2qDXsL37', 4, '{"title":"第20300243条・经筋第十三","description":"<p>13、足之阳明。手之太阳。筋急则口目为僻。眦急不能卒视。治皆如右方也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300243,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '13、足之阳明。手之太阳。筋急则口目为僻。眦急不能卒视。治皆如右方也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5Tj9iLf9XQT');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uHp6ycfj5mK', 4, '{"title":"第20300244条・骨度第十四","description":"<p>1、黄帝问于伯高曰。脉度言经脉之长短。何以立之。伯高曰。先度其骨节之大小。广狭。长短。而脉度定矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300244,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝问于伯高曰。脉度言经脉之长短。何以立之。伯高曰。先度其骨节之大小。广狭。长短。而脉度定矣。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hro5wkfbElD', 4, '{"title":"第20300245条・骨度第十四","description":"<p>2、黄帝曰。愿闻众人之度。人长七尺五寸者。其骨节之大小长短各几何。伯高曰。头之大骨围。二尺六寸。胸围四尺五寸。腰围四尺二寸。发所覆者颅至项。尺二寸。发以下至颐。长一尺。君子终折。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300245,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、黄帝曰。愿闻众人之度。人长七尺五寸者。其骨节之大小长短各几何。伯高曰。头之大骨围。二尺六寸。胸围四尺五寸。腰围四尺二寸。发所覆者颅至项。尺二寸。发以下至颐。长一尺。君子终折。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O2GHqk47xtc', 4, '{"title":"第20300246条・骨度第十四","description":"<p>3、结喉以下至缺盆中。长四寸。缺盆以下至𩩲骬。长九寸。过则肺大。不满则肺小。𩩲骬以下至天枢。长八寸。过则胃大。不及则胃小。天枢以下至横骨。长六寸半。过则回肠广长。不满则狭短。横骨。长六寸半。横骨上廉以下至内辅之上廉。长一尺八寸。内辅之上廉以下至下廉。长三寸半。内辅下廉。下至内踝。长一尺三寸。内踝以下至地。长三寸。膝腘以下至附属。长一尺六寸。附属以下至地。长三寸。故骨围大则太过。小则不及。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300246,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、结喉以下至缺盆中。长四寸。缺盆以下至𩩲骬。长九寸。过则肺大。不满则肺小。𩩲骬以下至天枢。长八寸。过则胃大。不及则胃小。天枢以下至横骨。长六寸半。过则回肠广长。不满则狭短。横骨。长六寸半。横骨上廉以下至内辅之上廉。长一尺八寸。内辅之上廉以下至下廉。长三寸半。内辅下廉。下至内踝。长一尺三寸。内踝以下至地。长三寸。膝腘以下至附属。长一尺六寸。附属以下至地。长三寸。故骨围大则太过。小则不及。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7gab796s5qx', 4, '{"title":"第20300247条・骨度第十四","description":"<p>4、角以下至柱骨。长一尺。行腋中不见者。长四寸。腋以下至季胁。长一尺二寸。季胁以下至髀枢。长六寸。髀枢以下至膝中。长一尺九寸。膝以下至外踝。长一尺六寸。外踝以下至京骨。长三寸。京骨以下至地。长一寸。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300247,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、角以下至柱骨。长一尺。行腋中不见者。长四寸。腋以下至季胁。长一尺二寸。季胁以下至髀枢。长六寸。髀枢以下至膝中。长一尺九寸。膝以下至外踝。长一尺六寸。外踝以下至京骨。长三寸。京骨以下至地。长一寸。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6tMrMvn4Yu7', 4, '{"title":"第20300248条・骨度第十四","description":"<p>5、耳后当完骨者。广九寸。耳前当耳门者。广一尺三寸。两颧之间。相去七寸。两乳之间。广九寸半。两髀之间。广六寸半。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300248,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、耳后当完骨者。广九寸。耳前当耳门者。广一尺三寸。两颧之间。相去七寸。两乳之间。广九寸半。两髀之间。广六寸半。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Huad94DtW1S', 4, '{"title":"第20300249条・骨度第十四","description":"<p>6、足长一尺二寸。广四寸半。肩至肘。长一尺七寸。肘至腕。长一尺二寸半。腕至中指本节。长四寸。本节至其末。长四寸半。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300249,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '6、足长一尺二寸。广四寸半。肩至肘。长一尺七寸。肘至腕。长一尺二寸半。腕至中指本节。长四寸。本节至其末。长四寸半。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5PxUoZSdhfI', 4, '{"title":"第20300250条・骨度第十四","description":"<p>7、项发以下至背骨。长二寸半。膂骨以下至尾骶二十一节。长三尺。上节长一寸四分分之一。奇分在下。故上七节至于膂骨。九寸八分分之七。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300250,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '7、项发以下至背骨。长二寸半。膂骨以下至尾骶二十一节。长三尺。上节长一寸四分分之一。奇分在下。故上七节至于膂骨。九寸八分分之七。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CBT0S5SacVM', 4, '{"title":"第20300251条・骨度第十四","description":"<p>8、此众人骨之度也。所以立经脉之长短也。是故视其经脉之在于身也。其见浮而坚。其见明而大者。多血。细而沉者。多气也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300251,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '8、此众人骨之度也。所以立经脉之长短也。是故视其经脉之在于身也。其见浮而坚。其见明而大者。多血。细而沉者。多气也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'wjif1aRqwIL');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lmDfphBD91M', 4, '{"title":"第20300252条・五十营第十五","description":"<p>1、黄帝曰。余愿闻五十营奈何。岐伯答曰。天周二十八宿。宿三十六分。人气行一周。千八分。日行二十八宿。人经脉上下左右前后二十八脉。周身十六丈二尺。以应二十八宿。漏水下百刻。以分昼夜。故人一呼脉再动。气行三寸。呼吸定息。气行六寸。十息。气行六尺。日行二分。二百七十息。气行十六丈二尺。气行交通于中。一周于身。下水二刻。日行二十五分。五百四十息。气行再周于身。下水四刻。日行四十分。二千七百息。气行十周于身。下水二十刻。日行五宿二十分。一万三千五百息。气行五十营于身。水下百刻。日行二十八宿。漏水皆尽脉终矣。所谓交通者。并行一数也。故五十营备。得尽天地之寿矣。凡行八百一十丈也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300252,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝曰。余愿闻五十营奈何。岐伯答曰。天周二十八宿。宿三十六分。人气行一周。千八分。日行二十八宿。人经脉上下左右前后二十八脉。周身十六丈二尺。以应二十八宿。漏水下百刻。以分昼夜。故人一呼脉再动。气行三寸。呼吸定息。气行六寸。十息。气行六尺。日行二分。二百七十息。气行十六丈二尺。气行交通于中。一周于身。下水二刻。日行二十五分。五百四十息。气行再周于身。下水四刻。日行四十分。二千七百息。气行十周于身。下水二十刻。日行五宿二十分。一万三千五百息。气行五十营于身。水下百刻。日行二十八宿。漏水皆尽脉终矣。所谓交通者。并行一数也。故五十营备。得尽天地之寿矣。凡行八百一十丈也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'hRMkglie7qo');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aPXOoNSgX2e', 4, '{"title":"第20300253条・营气第十六","description":"<p>1、黄帝曰。营气之道。内谷为宝。谷入于胃。乃传之肺。流溢于中。布散于外。精专者。行于经隧。常营无已。终而复始。是谓天地之纪。故气从太阴出注手阳明。上行注足阳明。下行至跗上。注大指间。与太阴合。上行抵髀。从脾注心中。循手少阴。出腋中臂。注小指。合手太阳。上行乘腋。出䪼内。注目内眦。上巅。下项。合足太阳。循脊。下尻。下行注小指之端。循足心。注足少阴。上行注肾。从肾注心外。散于胸中。循心主脉。出腋。下臂。出两筋之间。入掌中。出中指之端。还注小指次指之端。合手少阳。上行注膻中。散于三焦。从三焦注胆。出胁。注足少阳。下行至跗上。复从跗注大指间。合足厥阴。上行至肝。从肝上注肺。上循喉咙。入颃颡之窍。究于畜门。其支别者。上额。循巅。下项中。循脊入骶。是督脉也。络阴器。上过毛中。入脐中。上循腹里。入缺盆。下注肺中。复出太阴。此营气之所行也。逆顺之常也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300253,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝曰。营气之道。内谷为宝。谷入于胃。乃传之肺。流溢于中。布散于外。精专者。行于经隧。常营无已。终而复始。是谓天地之纪。故气从太阴出注手阳明。上行注足阳明。下行至跗上。注大指间。与太阴合。上行抵髀。从脾注心中。循手少阴。出腋中臂。注小指。合手太阳。上行乘腋。出䪼内。注目内眦。上巅。下项。合足太阳。循脊。下尻。下行注小指之端。循足心。注足少阴。上行注肾。从肾注心外。散于胸中。循心主脉。出腋。下臂。出两筋之间。入掌中。出中指之端。还注小指次指之端。合手少阳。上行注膻中。散于三焦。从三焦注胆。出胁。注足少阳。下行至跗上。复从跗注大指间。合足厥阴。上行至肝。从肝上注肺。上循喉咙。入颃颡之窍。究于畜门。其支别者。上额。循巅。下项中。循脊入骶。是督脉也。络阴器。上过毛中。入脐中。上循腹里。入缺盆。下注肺中。复出太阴。此营气之所行也。逆顺之常也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'USM1ILLmIdv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sjSl5Qe3rOD', 4, '{"title":"第20300254条・脉度第十七","description":"<p>1、黄帝曰。愿闻脉度。岐伯答曰。手之六阳。从手至头。长五尺。五六三丈。手之六阴。从手至胸中。三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足之六阳。从足上至头。八尺。六八四丈八尺。足之六阴。从足至胸中。六尺五寸。六六三丈六尺。五六三尺合三丈九尺。蹻脉从足至目。七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各四尺五寸。二四八尺。二五一尺。合九尺。凡都合一十六丈二尺。此气之大经隧也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300254,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝曰。愿闻脉度。岐伯答曰。手之六阳。从手至头。长五尺。五六三丈。手之六阴。从手至胸中。三尺五寸。三六一丈八尺。五六三尺。合二丈一尺。足之六阳。从足上至头。八尺。六八四丈八尺。足之六阴。从足至胸中。六尺五寸。六六三丈六尺。五六三尺合三丈九尺。蹻脉从足至目。七尺五寸。二七一丈四尺。二五一尺。合一丈五尺。督脉。任脉。各四尺五寸。二四八尺。二五一尺。合九尺。凡都合一十六丈二尺。此气之大经隧也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'nQub1RiHLbw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ngLNKSN4Kbg', 4, '{"title":"第20300255条・脉度第十七","description":"<p>2、经脉为里。支而横者为络。络之别者为孙。盛而血者疾诛之。盛者泻之。虚者饮药以补之。五藏常内阅于上七窍也。故肺气通于鼻。肺和则鼻能知臭香矣。心气通于舌。心和则舌能知五味矣。肝气通于目。肝和则目能辨五色矣。脾气通于口。脾和则口能知五谷矣。肾气通于耳。肾和则耳能闻五音矣。五藏不和。则七窍不通。六府不合则留为痈。故邪在府则阳脉不和。阳脉不和则气留之。气留之则阳气盛矣。阳气太盛。则阴不利。阴脉不利则血留之。血留之则阴气盛矣。阴气太盛则阳气不能荣也。故曰关。阳气太盛。则阴气弗能荣也。故曰格。阴阳俱盛。不得相荣。故曰关格。关格者。不得尽期而死也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300255,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、经脉为里。支而横者为络。络之别者为孙。盛而血者疾诛之。盛者泻之。虚者饮药以补之。五藏常内阅于上七窍也。故肺气通于鼻。肺和则鼻能知臭香矣。心气通于舌。心和则舌能知五味矣。肝气通于目。肝和则目能辨五色矣。脾气通于口。脾和则口能知五谷矣。肾气通于耳。肾和则耳能闻五音矣。五藏不和。则七窍不通。六府不合则留为痈。故邪在府则阳脉不和。阳脉不和则气留之。气留之则阳气盛矣。阳气太盛。则阴不利。阴脉不利则血留之。血留之则阴气盛矣。阴气太盛则阳气不能荣也。故曰关。阳气太盛。则阴气弗能荣也。故曰格。阴阳俱盛。不得相荣。故曰关格。关格者。不得尽期而死也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'nQub1RiHLbw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o3UErbdNElM', 4, '{"title":"第20300256条・脉度第十七","description":"<p>3、黄帝曰。蹻脉安起安止。何气荣水。岐伯答曰。蹻脉者。少阴之别。起于然骨之后。上内踝之上。直上循阴股。入阴。上循胸里。入缺盆。上出人迎之前。入頄。属目内眦。合于太阳。阳蹻而上行。气并相还。则为濡。目气不荣。则目不合。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300256,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、黄帝曰。蹻脉安起安止。何气荣水。岐伯答曰。蹻脉者。少阴之别。起于然骨之后。上内踝之上。直上循阴股。入阴。上循胸里。入缺盆。上出人迎之前。入頄。属目内眦。合于太阳。阳蹻而上行。气并相还。则为濡。目气不荣。则目不合。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'nQub1RiHLbw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xKXKfoLkhNI', 4, '{"title":"第20300257条・脉度第十七","description":"<p>4、黄帝曰。气独行五藏。不荣六府。何也。岐伯答曰。气之不得无行也。如水之流。如日月之行不休。故阴脉荣其藏。阳脉荣其府。如环之无端。莫知其纪。终而复始。其流溢之气。内溉藏府。外濡腠理。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300257,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、黄帝曰。气独行五藏。不荣六府。何也。岐伯答曰。气之不得无行也。如水之流。如日月之行不休。故阴脉荣其藏。阳脉荣其府。如环之无端。莫知其纪。终而复始。其流溢之气。内溉藏府。外濡腠理。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'nQub1RiHLbw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2mdmKSbYO0k', 4, '{"title":"第20300258条・脉度第十七","description":"<p>5、黄帝曰。蹻脉有阴阳。何脉当其数。岐伯曰。男子数其阳。女子数其阴。当数者为阴。其不当数者为络也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300258,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、黄帝曰。蹻脉有阴阳。何脉当其数。岐伯曰。男子数其阳。女子数其阴。当数者为阴。其不当数者为络也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'nQub1RiHLbw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jQj2DcnLrG8', 4, '{"title":"第20300259条・营卫生会第十八","description":"<p>1、黄帝问于岐伯曰。人焉受气。阴阳焉会。何气为营。何气为卫。营安从生。卫于焉会。老壮不同气。阴阳异位。愿闻其会。岐伯答曰。人受气于谷。谷入于胃。以传与肺。五藏六府。皆以受气。其清者为营。浊者为卫。营在脉中。卫在脉外。营周不休。五十度而复大会。阴阳相贯。如环无端。卫气行于阴二十五度。行于阳二十五度。分为昼夜。故气至阳而起。至阴而止。故曰日中而阳陇。为重阳。夜半而阴陇为重阴。故太阴主内。太阳主外。各行二十五度分为昼夜。夜半为阴陇。夜半后而为阴衰。平且阴尽而阳受气矣。日中而阳陇。日西而阳衰。日入阳尽而阴受气矣。夜半而大会。万民皆卧。命曰合阴。平旦阴尽而阳受气。如是无己。与天地同纪。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300259,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝问于岐伯曰。人焉受气。阴阳焉会。何气为营。何气为卫。营安从生。卫于焉会。老壮不同气。阴阳异位。愿闻其会。岐伯答曰。人受气于谷。谷入于胃。以传与肺。五藏六府。皆以受气。其清者为营。浊者为卫。营在脉中。卫在脉外。营周不休。五十度而复大会。阴阳相贯。如环无端。卫气行于阴二十五度。行于阳二十五度。分为昼夜。故气至阳而起。至阴而止。故曰日中而阳陇。为重阳。夜半而阴陇为重阴。故太阴主内。太阳主外。各行二十五度分为昼夜。夜半为阴陇。夜半后而为阴衰。平且阴尽而阳受气矣。日中而阳陇。日西而阳衰。日入阳尽而阴受气矣。夜半而大会。万民皆卧。命曰合阴。平旦阴尽而阳受气。如是无己。与天地同纪。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yMHRDPnGeQh', 4, '{"title":"第20300260条・营卫生会第十八","description":"<p>2、黄帝曰。老人之不夜瞑者。何气使然。少壮之人。不昼瞑者。何气使然。岐伯答曰。壮者之气血盛。其肌肉滑。气道通。营卫之行不失其常。故昼精而夜瞑。老者之气血衰。其肌肉枯。气道涩。五藏之气相博。其营气衰少而卫气内伐。故昼不精。夜不瞑。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300260,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、黄帝曰。老人之不夜瞑者。何气使然。少壮之人。不昼瞑者。何气使然。岐伯答曰。壮者之气血盛。其肌肉滑。气道通。营卫之行不失其常。故昼精而夜瞑。老者之气血衰。其肌肉枯。气道涩。五藏之气相博。其营气衰少而卫气内伐。故昼不精。夜不瞑。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rTpE81FO7Ed', 4, '{"title":"第20300261条・营卫生会第十八","description":"<p>3、黄帝曰。愿闻营卫之所行。皆何道从来。岐伯答曰。营出中焦。卫出下焦。黄帝曰。愿闻三焦之所出。岐伯答曰。上焦出于胃上口。并咽以上。贯膈。而布胸中。走腋。循太阴之分而行。还至阳明。上至舌。下足阳明。常与营俱行于阳二十五度。行于阴亦二十五度一周也。故五十度而复大会于手太阴矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300261,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、黄帝曰。愿闻营卫之所行。皆何道从来。岐伯答曰。营出中焦。卫出下焦。黄帝曰。愿闻三焦之所出。岐伯答曰。上焦出于胃上口。并咽以上。贯膈。而布胸中。走腋。循太阴之分而行。还至阳明。上至舌。下足阳明。常与营俱行于阳二十五度。行于阴亦二十五度一周也。故五十度而复大会于手太阴矣。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2AtGe2Ih0Q8', 4, '{"title":"第20300262条・营卫生会第十八","description":"<p>4、黄帝曰。人有热。饮食下胃。其气未定。汗则出。或出于面。或出于背。或出于身半。其不循卫气之道而出。何也。岐伯曰。此外伤于风。内开腠理。毛蒸理泄。卫气走之。固不得循其道。此气慓悍滑疾。见开而出。故不得从其道。故命曰漏泄。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300262,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、黄帝曰。人有热。饮食下胃。其气未定。汗则出。或出于面。或出于背。或出于身半。其不循卫气之道而出。何也。岐伯曰。此外伤于风。内开腠理。毛蒸理泄。卫气走之。固不得循其道。此气慓悍滑疾。见开而出。故不得从其道。故命曰漏泄。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uUyUYfPhd35', 4, '{"title":"第20300263条・营卫生会第十八","description":"<p>5、黄帝曰。愿闻中焦之所出。岐伯答曰。中焦亦并胃中。出上焦之后。此所受气者。泌糟粕。蒸津液。化其精微。上注于肺脉乃化而为血。以奉生身。莫贵于此。故独得行于经隧。命曰营气。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300263,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、黄帝曰。愿闻中焦之所出。岐伯答曰。中焦亦并胃中。出上焦之后。此所受气者。泌糟粕。蒸津液。化其精微。上注于肺脉乃化而为血。以奉生身。莫贵于此。故独得行于经隧。命曰营气。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0phqiI27UFz', 4, '{"title":"第20300264条・营卫生会第十八","description":"<p>6、黄帝曰。夫血之与气。异名同类。何谓也。岐伯答曰。营卫者。精气也。血者。神气也。故血之与气。异名同类焉。故夺血者无汗。夺汗者无血。故人生有两死而无两生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300264,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '6、黄帝曰。夫血之与气。异名同类。何谓也。岐伯答曰。营卫者。精气也。血者。神气也。故血之与气。异名同类焉。故夺血者无汗。夺汗者无血。故人生有两死而无两生。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vDMCD8AiOzO', 4, '{"title":"第20300265条・营卫生会第十八","description":"<p>7、黄帝曰。愿闻下焦之所出。岐伯答曰。下焦者。别回肠。注于膀胱。而渗入焉。故水谷者。常并居于胃中。成糟粕。而俱下于大肠而成下焦。渗而俱下。济泌别汁。循下焦而渗入膀胱焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300265,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '7、黄帝曰。愿闻下焦之所出。岐伯答曰。下焦者。别回肠。注于膀胱。而渗入焉。故水谷者。常并居于胃中。成糟粕。而俱下于大肠而成下焦。渗而俱下。济泌别汁。循下焦而渗入膀胱焉。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AIw6Tym7swy', 4, '{"title":"第20300266条・营卫生会第十八","description":"<p>8、黄帝曰。人饮酒。酒亦入胃。谷未熟。而小便独先下。何也。岐伯答曰。酒者。熟谷之液也。其气悍以清。故后谷而入。先谷而液出焉。黄帝曰。善。余闻上焦如雾。中焦如沤。下焦如渎。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300266,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '8、黄帝曰。人饮酒。酒亦入胃。谷未熟。而小便独先下。何也。岐伯答曰。酒者。熟谷之液也。其气悍以清。故后谷而入。先谷而液出焉。黄帝曰。善。余闻上焦如雾。中焦如沤。下焦如渎。此之谓也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'LMaqli3ezPQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N470AgYYytO', 4, '{"title":"第20300267条・四时气第十九","description":"<p>1、黄帝问于岐伯曰。夫四时之气。各不同形。百病之起。皆有所生。灸刺之道。何者为定。岐伯答曰。四时之气。各有所在。灸刺之道。得气穴为定。故春取经。血脉。分肉之间。甚者。深刺之。间者。浅刺之。夏取盛经孙络。取分间绝皮肤。秋取经俞。邪在府。取之合。冬取井荥。必深以留之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300267,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、黄帝问于岐伯曰。夫四时之气。各不同形。百病之起。皆有所生。灸刺之道。何者为定。岐伯答曰。四时之气。各有所在。灸刺之道。得气穴为定。故春取经。血脉。分肉之间。甚者。深刺之。间者。浅刺之。夏取盛经孙络。取分间绝皮肤。秋取经俞。邪在府。取之合。冬取井荥。必深以留之。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kJjCz2dPts1', 4, '{"title":"第20300268条・四时气第十九","description":"<p>2、温疟汗不出。为五十九痏。风㽷肤胀。为五十痏。取皮肤之血者。尽取之。飧泄补三阴之上。补阴陵泉。皆久留之。热行乃止。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300268,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、温疟汗不出。为五十九痏。风㽷肤胀。为五十痏。取皮肤之血者。尽取之。飧泄补三阴之上。补阴陵泉。皆久留之。热行乃止。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VUnGsk364l2', 4, '{"title":"第20300269条・四时气第十九","description":"<p>3、转筋于阳。治其阳。转筋于阴。治其阴。皆卒刺之。徒㽷先取环谷下三寸。以铍针针之。已刺而筩之。而内之。入而复之。以尽其㽷。必坚。来缓则烦悗。来急则安静。间日一刺之。㽷尽乃止。饮闭药。方刺之时徒饮之。方饮无食。方食无饮。无食他食。百三十五日。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300269,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、转筋于阳。治其阳。转筋于阴。治其阴。皆卒刺之。徒㽷先取环谷下三寸。以铍针针之。已刺而筩之。而内之。入而复之。以尽其㽷。必坚。来缓则烦悗。来急则安静。间日一刺之。㽷尽乃止。饮闭药。方刺之时徒饮之。方饮无食。方食无饮。无食他食。百三十五日。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JFwnZYS4Oka', 4, '{"title":"第20300270条・四时气第十九","description":"<p>4、着痹不去。久寒不已。卒取其三里。骨为干。肠中不便。取三里。盛泻之。虚补之。疠风者。素刺其肿上。已刺。以锐针针其处。按出其恶气。肿尽乃止。常食方食。无食他食。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300270,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、着痹不去。久寒不已。卒取其三里。骨为干。肠中不便。取三里。盛泻之。虚补之。疠风者。素刺其肿上。已刺。以锐针针其处。按出其恶气。肿尽乃止。常食方食。无食他食。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8c1mKy9zsDS', 4, '{"title":"第20300271条・四时气第十九","description":"<p>5、腹中常鸣。气上冲胸。喘不能久立。邪在大肠。刺肓之原。巨虚上廉。三里。小腹控睪。引腰脊。上冲心。邪在小肠者。连睪系。属于脊。贯肝肺。络心系。气盛则厥逆。上冲肠胃。熏肝。散于肓。结于脐。故取之肓原以散之。刺太阴以予之。取厥阴以下之。取巨虚下廉以去之。按其所过之经以调之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300271,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、腹中常鸣。气上冲胸。喘不能久立。邪在大肠。刺肓之原。巨虚上廉。三里。小腹控睪。引腰脊。上冲心。邪在小肠者。连睪系。属于脊。贯肝肺。络心系。气盛则厥逆。上冲肠胃。熏肝。散于肓。结于脐。故取之肓原以散之。刺太阴以予之。取厥阴以下之。取巨虚下廉以去之。按其所过之经以调之。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o9BYC4KgozH', 4, '{"title":"第20300272条・四时气第十九","description":"<p>6、善呕。呕有苦。长太息。心中憺憺。恐人将捕之。邪在胆。逆在胃。胆液泄。则口苦。胃气逆。则呕苦。故曰呕胆。取三里以下。胃气逆。则刺少阳血络。以闭胆逆。却调其虚实。以去其邪。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300272,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '6、善呕。呕有苦。长太息。心中憺憺。恐人将捕之。邪在胆。逆在胃。胆液泄。则口苦。胃气逆。则呕苦。故曰呕胆。取三里以下。胃气逆。则刺少阳血络。以闭胆逆。却调其虚实。以去其邪。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cQevqHOPBxX', 4, '{"title":"第20300273条・四时气第十九","description":"<p>7、饮食不下。膈塞不通。邪在胃脘。在上脘。则刺抑而下之。在下脘。则散而去之。小腹痛肿。不得小便。邪在三焦。约取之太阳大络。视其络脉与厥阴小络结而血者。肿上及胃脘。取三里。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300273,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '7、饮食不下。膈塞不通。邪在胃脘。在上脘。则刺抑而下之。在下脘。则散而去之。小腹痛肿。不得小便。邪在三焦。约取之太阳大络。视其络脉与厥阴小络结而血者。肿上及胃脘。取三里。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VwvLHYXrv3f', 4, '{"title":"第20300274条・四时气第十九","description":"<p>8、睹其色。察其以。知其散复者。视其目色。以知病之存亡也。一其形。听其动静者。持气口人迎以视其脉。坚且盛且滑者。病日进。脉软者。病将下。诸经实者。病三日已。气口候阴。人迎候阳也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300274,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '8、睹其色。察其以。知其散复者。视其目色。以知病之存亡也。一其形。听其动静者。持气口人迎以视其脉。坚且盛且滑者。病日进。脉软者。病将下。诸经实者。病三日已。气口候阴。人迎候阳也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 's5kIyu6wEsH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ukxct16HOe3', 4, '{"title":"第20300275条・五邪第二十","description":"<p>1、邪在肺。则病皮肤痛。寒热。上气喘。汗出。欬动肩背。取之膺中外喻。背三节五藏之傍。以手疾按之。快然。乃刺之。取之缺盆中以越之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300275,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '1、邪在肺。则病皮肤痛。寒热。上气喘。汗出。欬动肩背。取之膺中外喻。背三节五藏之傍。以手疾按之。快然。乃刺之。取之缺盆中以越之。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ET7XQiuY0Kr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o74L680e66x', 4, '{"title":"第20300276条・五邪第二十","description":"<p>2、邪在肝。则两胁中痛。寒中。恶血在内。行善掣节。时脚肿。取之行间。以引胁下。补三里以温胃中。取血脉以散恶血。取耳间青脉。以去其掣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300276,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2、邪在肝。则两胁中痛。寒中。恶血在内。行善掣节。时脚肿。取之行间。以引胁下。补三里以温胃中。取血脉以散恶血。取耳间青脉。以去其掣。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ET7XQiuY0Kr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0YzQuFWgtzU', 4, '{"title":"第20300277条・五邪第二十","description":"<p>3、邪在脾胃。则病肌肉痛。阳气有余。阴气不足。则热中善饥。阳气不足。阴气有余。则寒中肠鸣。腹痛。阴阳俱有余。若俱不足。则有寒有热。皆调于三里。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300277,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '3、邪在脾胃。则病肌肉痛。阳气有余。阴气不足。则热中善饥。阳气不足。阴气有余。则寒中肠鸣。腹痛。阴阳俱有余。若俱不足。则有寒有热。皆调于三里。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ET7XQiuY0Kr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('etvg53Pb7Lx', 4, '{"title":"第20300278条・五邪第二十","description":"<p>4、邪在肾。则病骨痛。阴痹。阴痹者。按之而不得。腹胀。腰痛。大便难。肩背颈项痛。时眩。取之涌泉。昆仑。视有血者。尽取之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300278,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '4、邪在肾。则病骨痛。阴痹。阴痹者。按之而不得。腹胀。腰痛。大便难。肩背颈项痛。时眩。取之涌泉。昆仑。视有血者。尽取之。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ET7XQiuY0Kr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ciAi2g5r7VH', 4, '{"title":"第20300279条・五邪第二十","description":"<p>5、邪在心。则病心痛。喜悲时眩仆。视有余不足而调之其输也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300279,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '2024-09-26T13:54:45.000Z', '5、邪在心。则病心痛。喜悲时眩仆。视有余不足而调之其输也。', '2024-09-26T13:54:45.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ET7XQiuY0Kr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fOsMJosTV81', 4, '{"title":"第20300280条・寒热病第二十一","description":"<p>1、皮寒热者。不可附席。毛发焦。鼻槁腊。不得汗。取三阳之络。以补手太阴。肌寒热者。肌痛。毛发焦而唇槁腊。不得汗。取三阳于下。以去其血者。补足太阴。以出其汗。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300280,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、皮寒热者。不可附席。毛发焦。鼻槁腊。不得汗。取三阳之络。以补手太阴。肌寒热者。肌痛。毛发焦而唇槁腊。不得汗。取三阳于下。以去其血者。补足太阴。以出其汗。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D1a5DzHpyzY', 4, '{"title":"第20300281条・寒热病第二十一","description":"<p>2、骨寒热者。病无所安。汗注不休。齿未槁。取其少阴于阴股之络。齿已槁。死不治。骨厥亦然。骨痹。举节不用而痛。汗注。烦心。取三阴之经。补之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300281,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、骨寒热者。病无所安。汗注不休。齿未槁。取其少阴于阴股之络。齿已槁。死不治。骨厥亦然。骨痹。举节不用而痛。汗注。烦心。取三阴之经。补之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bY0nzpnbuZI', 4, '{"title":"第20300282条・寒热病第二十一","description":"<p>3、身有所伤。血出多及中风寒。若有所堕坠。四肢懈惰不收。名曰体惰。取其小腹脐下三结交。三结交者。阳明太阴也。脐下三寸关元也。厥痹者。厥气上及腹。取阴阳之络。视主病也。泻阳补阴经也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300282,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、身有所伤。血出多及中风寒。若有所堕坠。四肢懈惰不收。名曰体惰。取其小腹脐下三结交。三结交者。阳明太阴也。脐下三寸关元也。厥痹者。厥气上及腹。取阴阳之络。视主病也。泻阳补阴经也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4olc81QXhyZ', 4, '{"title":"第20300283条・寒热病第二十一","description":"<p>4、颈侧之动脉人迎。人迎。足阳明也。在婴筋之前。婴筋之后。手阳明也。名曰扶突。次脉。足少阳脉也。名曰天牖。次脉。足太阳也。名曰天柱。腋下动脉。臂太阴也。名曰天府。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300283,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、颈侧之动脉人迎。人迎。足阳明也。在婴筋之前。婴筋之后。手阳明也。名曰扶突。次脉。足少阳脉也。名曰天牖。次脉。足太阳也。名曰天柱。腋下动脉。臂太阴也。名曰天府。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZLlkYD1G4uR', 4, '{"title":"第20300284条・寒热病第二十一","description":"<p>5、阳迎头痛。胸满不得息。取之人迎。暴瘖气鞭。取扶突与舌本出血。暴袭气蒙。耳目不明。取天牖。暴挛痫眩。足不任身。取天柱。暴痹内逆。肝肺相搏。血溢鼻口。取天府。此为天牖五部。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300284,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、阳迎头痛。胸满不得息。取之人迎。暴瘖气鞭。取扶突与舌本出血。暴袭气蒙。耳目不明。取天牖。暴挛痫眩。足不任身。取天柱。暴痹内逆。肝肺相搏。血溢鼻口。取天府。此为天牖五部。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3cJ9A4ka4lQ', 4, '{"title":"第20300285条・寒热病第二十一","description":"<p>6、臂阳明。有入頄遍齿者。名曰大迎。下齿龋。取之臂。恶寒补之。不恶寒泻之。足太阳有入頄遍齿者。名曰角孙。上齿龋。取之在鼻与頄前。方病之时。其脉盛。盛则泻之。虚则补之。一曰取之出鼻外。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300285,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、臂阳明。有入頄遍齿者。名曰大迎。下齿龋。取之臂。恶寒补之。不恶寒泻之。足太阳有入頄遍齿者。名曰角孙。上齿龋。取之在鼻与頄前。方病之时。其脉盛。盛则泻之。虚则补之。一曰取之出鼻外。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('abfQWzHY2UT', 4, '{"title":"第20300286条・寒热病第二十一","description":"<p>7、足阳明有挟鼻入于面者。名曰悬颅。属口。对入系目本。视有过者取之。损有余。益不足。反者益其。足太阳有通项入于脑者。正属目本。名曰眼系。头目苦痛。取之在项中两筋间。入脑乃别阴蹻。阳蹻。阴阳相交。阳入阴。阴出阳。交于目锐眦。阳气盛则瞋目。阴气盛则瞑目。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300286,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '7、足阳明有挟鼻入于面者。名曰悬颅。属口。对入系目本。视有过者取之。损有余。益不足。反者益其。足太阳有通项入于脑者。正属目本。名曰眼系。头目苦痛。取之在项中两筋间。入脑乃别阴蹻。阳蹻。阴阳相交。阳入阴。阴出阳。交于目锐眦。阳气盛则瞋目。阴气盛则瞑目。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XGFuubFYals', 4, '{"title":"第20300287条・寒热病第二十一","description":"<p>8、热厥取足太阴。少阳。皆留之。寒厥取足阳明。少阴于足。皆留之。舌纵涎下。烦悗。取足少阴。振寒洒洒鼓颔。不得汗出。腹胀烦悗。取手太阴。刺虚者。刺其去也。刺实者。刺其来也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300287,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '8、热厥取足太阴。少阳。皆留之。寒厥取足阳明。少阴于足。皆留之。舌纵涎下。烦悗。取足少阴。振寒洒洒鼓颔。不得汗出。腹胀烦悗。取手太阴。刺虚者。刺其去也。刺实者。刺其来也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vs4hOYptEPg', 4, '{"title":"第20300288条・寒热病第二十一","description":"<p>9、春取络脉。夏取分腠。秋取气口。冬取经输。凡此四时。各以时为齐。络脉治皮肤。分腠治肌肉。气口治筋脉。经输治骨髓。五藏。身有五部。伏兔一。腓二。腓者腨也。背三。五藏之输四。项五。此五部有痈疽者死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300288,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '9、春取络脉。夏取分腠。秋取气口。冬取经输。凡此四时。各以时为齐。络脉治皮肤。分腠治肌肉。气口治筋脉。经输治骨髓。五藏。身有五部。伏兔一。腓二。腓者腨也。背三。五藏之输四。项五。此五部有痈疽者死。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MSRrcTjgpbl', 4, '{"title":"第20300289条・寒热病第二十一","description":"<p>10、病始手臂者。先取手阳明。太阴而汗出。病始头首者。先取项太阳而汗出。病始足胫者。先取足阳明而汗出。臂太阴可汗出。足阳明可汗出。故取阴而汗出甚者。止之于阳。取阳而汗出甚者。止之于阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300289,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '10、病始手臂者。先取手阳明。太阴而汗出。病始头首者。先取项太阳而汗出。病始足胫者。先取足阳明而汗出。臂太阴可汗出。足阳明可汗出。故取阴而汗出甚者。止之于阳。取阳而汗出甚者。止之于阴。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2PbegSz9bJl', 4, '{"title":"第20300290条・寒热病第二十一","description":"<p>11、凡刺之害。中而不去则精泄。不中而去则致气。精泄则病甚而怄。致气则生为痈疽也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300290,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '11、凡刺之害。中而不去则精泄。不中而去则致气。精泄则病甚而怄。致气则生为痈疽也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ut4TtXsrh7n');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E0MVGvIXHs3', 4, '{"title":"第20300291条・癞狂病第二十二","description":"<p>1、目眦外决于面者。为锐眦。在内近鼻者。为内眦。上为外眦。下为内眦。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300291,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、目眦外决于面者。为锐眦。在内近鼻者。为内眦。上为外眦。下为内眦。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fAnDw6NMpcH', 4, '{"title":"第20300292条・癞狂病第二十二","description":"<p>2、癫疾始生。先不乐。头重痛。视举目赤。甚作极。已而烦心。候之于颜。取手太阳。阳明。太阴。血变为止。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300292,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、癫疾始生。先不乐。头重痛。视举目赤。甚作极。已而烦心。候之于颜。取手太阳。阳明。太阴。血变为止。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Bmz2Be8vBo', 4, '{"title":"第20300293条・癞狂病第二十二","description":"<p>3、癫疾始作。而引口啼呼喘悸者。候之手阳明。太阳。左强者。攻其右。右强者。攻其左。血变为止。癫疾始作。先反僵。因而脊痛。候之足太阳。阳明。太阴。手太阳。血变为止。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300293,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、癫疾始作。而引口啼呼喘悸者。候之手阳明。太阳。左强者。攻其右。右强者。攻其左。血变为止。癫疾始作。先反僵。因而脊痛。候之足太阳。阳明。太阴。手太阳。血变为止。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o4J5OyteBwK', 4, '{"title":"第20300294条・癞狂病第二十二","description":"<p>4、治癫疾者。常与之居。察其所当取之处。病至。视之有过者泻之。置其血于瓠壶之中。至其发时。血独动矣。不动。灸穷骨二十壮。穷骨者。骶骨也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300294,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、治癫疾者。常与之居。察其所当取之处。病至。视之有过者泻之。置其血于瓠壶之中。至其发时。血独动矣。不动。灸穷骨二十壮。穷骨者。骶骨也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Rshcqi5p6f', 4, '{"title":"第20300295条・癞狂病第二十二","description":"<p>5、骨癫疾者。顑。齿诸腧。分肉皆满而骨居。汗出。烦悗。呕多沃沫。气下泄。不治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300295,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、骨癫疾者。顑。齿诸腧。分肉皆满而骨居。汗出。烦悗。呕多沃沫。气下泄。不治。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zvQE7DXrLmk', 4, '{"title":"第20300296条・癞狂病第二十二","description":"<p>6、筋癫疾者。身倦挛急大。刺项大经之大杼脉。呕多沃沫。气下泄。不治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300296,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、筋癫疾者。身倦挛急大。刺项大经之大杼脉。呕多沃沫。气下泄。不治。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k0cCp68LdP6', 4, '{"title":"第20300297条・癞狂病第二十二","description":"<p>7、脉癫疾者。暴仆。四肢之脉皆胀而纵。脉满。尽刺之出血。不满。灸之项太阳。灸带脉于腰相去三寸。诸分肉本输。呕吐沃沫。气下泄。不治。癫疾者。疾发如狂者。死不治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300297,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '7、脉癫疾者。暴仆。四肢之脉皆胀而纵。脉满。尽刺之出血。不满。灸之项太阳。灸带脉于腰相去三寸。诸分肉本输。呕吐沃沫。气下泄。不治。癫疾者。疾发如狂者。死不治。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rmArzsL736O', 4, '{"title":"第20300298条・癞狂病第二十二","description":"<p>8、狂始生。先自悲也。喜忘。苦怒。善恐者得之忧饥。治之取手太阳。阳明。血变而止。及取足太阴。阳明。狂始发。少卧不饥。自高贤也。自辩智也。自尊贵也。善骂詈。日夜不休。治之取手阳明太阳太阴舌下少阴。视之盛者。皆取之。不盛。释之也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300298,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '8、狂始生。先自悲也。喜忘。苦怒。善恐者得之忧饥。治之取手太阳。阳明。血变而止。及取足太阴。阳明。狂始发。少卧不饥。自高贤也。自辩智也。自尊贵也。善骂詈。日夜不休。治之取手阳明太阳太阴舌下少阴。视之盛者。皆取之。不盛。释之也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('miXRWqr4EUd', 4, '{"title":"第20300299条・癞狂病第二十二","description":"<p>9、狂言。惊。善笑。好歌乐。妄行不休者。得之大恐。治之取手阳明太阳太阴。狂。目妄见。耳妄闻。善呼者。少气之所生也。治之取手太阳太阴阳明。足太阴头两顑。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300299,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '9、狂言。惊。善笑。好歌乐。妄行不休者。得之大恐。治之取手阳明太阳太阴。狂。目妄见。耳妄闻。善呼者。少气之所生也。治之取手太阳太阴阳明。足太阴头两顑。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iju5l3nNyhD', 4, '{"title":"第20300300条・癞狂病第二十二","description":"<p>10、狂者多食。善见鬼神。善笑而不发于外者。得之有所大喜。治之取足太阴太阳阳明。后取手太阴太阳阳明。狂而新发。未应如此者。先取曲泉左右动脉。及盛者见血。有顷已。不已。以法取之。灸骨骶二十壮。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300300,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '10、狂者多食。善见鬼神。善笑而不发于外者。得之有所大喜。治之取足太阴太阳阳明。后取手太阴太阳阳明。狂而新发。未应如此者。先取曲泉左右动脉。及盛者见血。有顷已。不已。以法取之。灸骨骶二十壮。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RPdlLTk7X8t', 4, '{"title":"第20300301条・癞狂病第二十二","description":"<p>11、风逆。暴四肢肿。身漯漯。唏然时寒。饥则烦。饱则善变。取手太表里。足少阴阳明之径。肉清取荥。骨清取井。经也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '11、风逆。暴四肢肿。身漯漯。唏然时寒。饥则烦。饱则善变。取手太表里。足少阴阳明之径。肉清取荥。骨清取井。经也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HDDzcDJ6tBK', 4, '{"title":"第20300302条・癞狂病第二十二","description":"<p>12、厥逆为病也。足暴清。胸若将裂。肠若将以刀切之。烦而不能食。脉大小皆涩。暖取足少阴。清取足阳明。清则补之。温则泻之。厥逆腹胀满。肠鸣。胸满不得息。取之下胸二胁。咳而动手者。与背输。以手按之。立快者是也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '12、厥逆为病也。足暴清。胸若将裂。肠若将以刀切之。烦而不能食。脉大小皆涩。暖取足少阴。清取足阳明。清则补之。温则泻之。厥逆腹胀满。肠鸣。胸满不得息。取之下胸二胁。咳而动手者。与背输。以手按之。立快者是也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a2cm70qCW5d', 4, '{"title":"第20300303条・癞狂病第二十二","description":"<p>13、内闭不得溲。刺足少阴太阳。与抵上以长针。气逆。则取其太阴。阳明。厥阴。甚取少阴。阳明。动者之经也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '13、内闭不得溲。刺足少阴太阳。与抵上以长针。气逆。则取其太阴。阳明。厥阴。甚取少阴。阳明。动者之经也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gid82YHP7VS', 4, '{"title":"第20300304条・癞狂病第二十二","description":"<p>14、少气。身漯漯也。言吸吸也。骨酸体重。懈惰不能动。补足少阴。短气息短。不属。动作气索。补足少阴。去血络也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '14、少气。身漯漯也。言吸吸也。骨酸体重。懈惰不能动。补足少阴。短气息短。不属。动作气索。补足少阴。去血络也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'SJxl1zjoNkP');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dAQRUYF90qM', 4, '{"title":"第20300305条・热病第二十三","description":"<p>1、偏枯。身偏不用而痛。言不变。志不乱。病在分腠之间。巨针取之。益其不足。损其有余。乃可复也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、偏枯。身偏不用而痛。言不变。志不乱。病在分腠之间。巨针取之。益其不足。损其有余。乃可复也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZJullo5ovDE', 4, '{"title":"第20300306条・热病第二十三","description":"<p>2、痱之为病也。身无痛者。四肢不收。智乱不甚。其言微知。可治。甚则不能言。不可治也。病先起于阳。复入于阴者。先取其阳。后取其阴。浮而取之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、痱之为病也。身无痛者。四肢不收。智乱不甚。其言微知。可治。甚则不能言。不可治也。病先起于阳。复入于阴者。先取其阳。后取其阴。浮而取之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YCY3S4e2aGK', 4, '{"title":"第20300307条・热病第二十三","description":"<p>3、热病三日。而气口静。人迎躁者。取之诸阳。五十九刺。以泻其热。而出其汗。实其阴。以补其不足者。身热甚。阴阳皆静者。勿刺也。其可刺者。急取之。不汗出则泄。所谓勿刺者。有死征也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、热病三日。而气口静。人迎躁者。取之诸阳。五十九刺。以泻其热。而出其汗。实其阴。以补其不足者。身热甚。阴阳皆静者。勿刺也。其可刺者。急取之。不汗出则泄。所谓勿刺者。有死征也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dsCZdrb64Ln', 4, '{"title":"第20300308条・热病第二十三","description":"<p>4、热病七日八日。脉口动。喘而短者。急刺之。汗且自出。浅刺手大指间。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、热病七日八日。脉口动。喘而短者。急刺之。汗且自出。浅刺手大指间。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AtRhJ56Qf9a', 4, '{"title":"第20300309条・热病第二十三","description":"<p>5、热病七日八日。脉微小。病者溲血。口中干。一日半而死。脉代者。一日死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、热病七日八日。脉微小。病者溲血。口中干。一日半而死。脉代者。一日死。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GEF2y5WWrml', 4, '{"title":"第20300310条・热病第二十三","description":"<p>6、热病已得汗出。而脉尚躁。喘且复热。勿刺肤。喘甚者死。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300310,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、热病已得汗出。而脉尚躁。喘且复热。勿刺肤。喘甚者死。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B6pRA475yDw', 4, '{"title":"第20300311条・热病第二十三","description":"<p>7、热病七日八日。脉不躁。躁不散改。后看中有汗。三日不汗。四日死。未曾汗者。勿腠刺之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300311,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '7、热病七日八日。脉不躁。躁不散改。后看中有汗。三日不汗。四日死。未曾汗者。勿腠刺之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q5DwjROEP1H', 4, '{"title":"第20300312条・热病第二十三","description":"<p>8、热病先肤痛。窒鼻充面。取之皮。以第一针。五十九。苛轸鼻。索皮于肺。不得。索之火。火者。心也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300312,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '8、热病先肤痛。窒鼻充面。取之皮。以第一针。五十九。苛轸鼻。索皮于肺。不得。索之火。火者。心也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qlLqW0ekfFU', 4, '{"title":"第20300313条・热病第二十三","description":"<p>9、热病先身涩倚而热。烦俛。干唇口溢。取之皮。以第一针。五十九。肤胀口干。寒汗出。索脉于心。不得。索之水。水者。肾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300313,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '9、热病先身涩倚而热。烦俛。干唇口溢。取之皮。以第一针。五十九。肤胀口干。寒汗出。索脉于心。不得。索之水。水者。肾也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lVymzB4tpCq', 4, '{"title":"第20300314条・热病第二十三","description":"<p>10、热病溢干多饮。善惊。卧不能起。取之肤肉。以第六针。五十九。目眦青。索肉于脾。不得。索之水。木者。肝也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300314,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '10、热病溢干多饮。善惊。卧不能起。取之肤肉。以第六针。五十九。目眦青。索肉于脾。不得。索之水。木者。肝也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jpbzuqO9l6K', 4, '{"title":"第20300315条・热病第二十三","description":"<p>11、热病面青。脑痛。手足躁。取之筋间。以第四针于四逆。筋躄目浸。索筋于肝。不得。索之金。金者。肺也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300315,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '11、热病面青。脑痛。手足躁。取之筋间。以第四针于四逆。筋躄目浸。索筋于肝。不得。索之金。金者。肺也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lpcksNcnWKS', 4, '{"title":"第20300316条・热病第二十三","description":"<p>12、热病数惊。瘈瘲而狂。取之脉。以第四针。急泻有余者。癫疾毛发去。索血于心。不得。索之水。水者。肾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300316,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '12、热病数惊。瘈瘲而狂。取之脉。以第四针。急泻有余者。癫疾毛发去。索血于心。不得。索之水。水者。肾也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7FR3cm20pbb', 4, '{"title":"第20300317条・热病第二十三","description":"<p>13、热病身重骨痛。耳聋而好瞑。取之骨。以第四针。五十九。刺骨。病不食。啮齿耳青。索骨于肾。不得。索之土。土者。脾也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300317,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '13、热病身重骨痛。耳聋而好瞑。取之骨。以第四针。五十九。刺骨。病不食。啮齿耳青。索骨于肾。不得。索之土。土者。脾也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e8X3TDJ0xFR', 4, '{"title":"第20300318条・热病第二十三","description":"<p>14、热病不知所痛。耳聋。不能自收。口干。阳热甚。阴颇有寒者。热在髓。死不可治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300318,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '14、热病不知所痛。耳聋。不能自收。口干。阳热甚。阴颇有寒者。热在髓。死不可治。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gCCj7wzNYZi', 4, '{"title":"第20300319条・热病第二十三","description":"<p>15、热病头痛。颞颥。目𤸪脉痛。善衄。厥热病也。取之以第三针。视有余不足。寒热痔。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300319,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '15、热病头痛。颞颥。目𤸪脉痛。善衄。厥热病也。取之以第三针。视有余不足。寒热痔。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dVSNvnlnSZN', 4, '{"title":"第20300320条・热病第二十三","description":"<p>16、热病。体重。肠中热。取之以第四针。于其俞。及下诸指间。索气于胃胳$a{应作络}得气也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300320,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '16、热病。体重。肠中热。取之以第四针。于其俞。及下诸指间。索气于胃胳$a{应作络}得气也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T6Tn91QlG85', 4, '{"title":"第20300321条・热病第二十三","description":"<p>17、热病挟脐急痛。胸胁满。取之涌泉与阴陵泉。取以第四针。针嗌里。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300321,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '17、热病挟脐急痛。胸胁满。取之涌泉与阴陵泉。取以第四针。针嗌里。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HHHeq38GTI3', 4, '{"title":"第20300322条・热病第二十三","description":"<p>18、热病。而汗且出。及脉顺可汗者。取之鱼际。太渊。大都。太白。泻之则热去。补之则汗出。汗出大甚。取内踝上横脉以止之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300322,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '18、热病。而汗且出。及脉顺可汗者。取之鱼际。太渊。大都。太白。泻之则热去。补之则汗出。汗出大甚。取内踝上横脉以止之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bl6wijTmN4x', 4, '{"title":"第20300323条・热病第二十三","description":"<p>19、热病已得汗而脉尚躁盛。此阴脉之极也。死。其得汗而脉静者。生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300323,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '19、热病已得汗而脉尚躁盛。此阴脉之极也。死。其得汗而脉静者。生。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('10De3g7zGPF', 4, '{"title":"第20300324条・热病第二十三","description":"<p>20、热病者。脉尚盛躁而不得汗者。此阳脉之极也。死。脉盛躁得汗静者。生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300324,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '20、热病者。脉尚盛躁而不得汗者。此阳脉之极也。死。脉盛躁得汗静者。生。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dpxq4Dw2kM3', 4, '{"title":"第20300325条・热病第二十三","description":"<p>21、热病不可刺者有九。一曰。汗不出。大颧发赤秽者死。二曰。泄而腹满甚者死。三曰。目不明。热不已者死。四曰。老人婴儿热而腹满者死。五曰。汗不出呕下血者死。六曰。舌本烂。热不已者死。七曰。咳而衄。汗不出。出不至足者死。八曰。髓热者死。九曰。热而痉者死。腰折。病病。齿噤也。凡此九者。不可刺也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300325,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '21、热病不可刺者有九。一曰。汗不出。大颧发赤秽者死。二曰。泄而腹满甚者死。三曰。目不明。热不已者死。四曰。老人婴儿热而腹满者死。五曰。汗不出呕下血者死。六曰。舌本烂。热不已者死。七曰。咳而衄。汗不出。出不至足者死。八曰。髓热者死。九曰。热而痉者死。腰折。病病。齿噤也。凡此九者。不可刺也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6dWwUzo0Pn4', 4, '{"title":"第20300326条・热病第二十三","description":"<p>22、所谓五十九刺者。两手外内侧各三。凡十二痏。五指间各一。凡八痏。足亦如是。头入发一寸旁三分各三。凡六痏。更入发三寸边五。凡十痏。耳前后口下者各一。项中一。凡六痏。巅上一。聪会一。发际一。廉泉一。风池二。天柱二。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300326,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '22、所谓五十九刺者。两手外内侧各三。凡十二痏。五指间各一。凡八痏。足亦如是。头入发一寸旁三分各三。凡六痏。更入发三寸边五。凡十痏。耳前后口下者各一。项中一。凡六痏。巅上一。聪会一。发际一。廉泉一。风池二。天柱二。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('D0QVJwAl2AF', 4, '{"title":"第20300327条・热病第二十三","description":"<p>23、气满胸中喘息。取足太阴大指之端。去爪甲如薤叶。寒则留之。热则疾之。气下乃止。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300327,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '23、气满胸中喘息。取足太阴大指之端。去爪甲如薤叶。寒则留之。热则疾之。气下乃止。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Yy6bPs6rk6p', 4, '{"title":"第20300328条・热病第二十三","description":"<p>24、心疝暴痛。取足太阴厥阴。尽刺去其血络。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300328,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '24、心疝暴痛。取足太阴厥阴。尽刺去其血络。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gkp8xWsL7vw', 4, '{"title":"第20300329条・热病第二十三","description":"<p>25、喉痹舌卷。口中干。烦心。心痛。臂内廉痛。不可及头。取手小指次指爪甲下。去端如韭叶。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300329,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '25、喉痹舌卷。口中干。烦心。心痛。臂内廉痛。不可及头。取手小指次指爪甲下。去端如韭叶。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ubTFYOR2yPC', 4, '{"title":"第20300330条・热病第二十三","description":"<p>26、目中赤痛。从内眦始。取之阴蹻。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300330,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '26、目中赤痛。从内眦始。取之阴蹻。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a1zfQBggjZH', 4, '{"title":"第20300331条・热病第二十三","description":"<p>27、风痉身反折。先取足太阳及腘中及血络出血。中有寒。取三里。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300331,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '27、风痉身反折。先取足太阳及腘中及血络出血。中有寒。取三里。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t67VDoFJz5C', 4, '{"title":"第20300332条・热病第二十三","description":"<p>28、癃。取之阴蹻及三毛上及血络出血。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300332,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '28、癃。取之阴蹻及三毛上及血络出血。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8eHa9rCIthv', 4, '{"title":"第20300333条・热病第二十三","description":"<p>29、男子如蛊。女子如怚。身体腰脊如解。不欲饮食。先取涌泉见血。视跗上盛者。尽见血也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300333,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '29、男子如蛊。女子如怚。身体腰脊如解。不欲饮食。先取涌泉见血。视跗上盛者。尽见血也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tm3Tye0chKN');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AsCYtzFW6pe', 4, '{"title":"第20300334条・厥病第二十四","description":"<p>1、厥头痛。面若肿起而烦心。取之足阳明太阴。厥头痛。头脉痛。心悲。善泣。视头动脉反盛者。刺尽去血。后调足厥阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300334,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、厥头痛。面若肿起而烦心。取之足阳明太阴。厥头痛。头脉痛。心悲。善泣。视头动脉反盛者。刺尽去血。后调足厥阴。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0qR8HIX9or0', 4, '{"title":"第20300335条・厥病第二十四","description":"<p>2、厥头痛。贞贞头重而痛。写头上五行。行五。先取手少阴。后取足少阴。厥头痛。意善忘。按之不得。取头面左右动脉。后取足太阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300335,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、厥头痛。贞贞头重而痛。写头上五行。行五。先取手少阴。后取足少阴。厥头痛。意善忘。按之不得。取头面左右动脉。后取足太阴。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5hr0IMtfKLj', 4, '{"title":"第20300336条・厥病第二十四","description":"<p>3、厥头痛。项先痛。腰脊为应。先取天柱。后取足太阳。厥头痛。头痛甚。耳前后脉涌有热。泻出其血。后取足少阳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300336,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、厥头痛。项先痛。腰脊为应。先取天柱。后取足太阳。厥头痛。头痛甚。耳前后脉涌有热。泻出其血。后取足少阳。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CyVn5rcEkWN', 4, '{"title":"第20300337条・厥病第二十四","description":"<p>4、真头痛。头痛甚。脑尽痛。手足寒至节。死不治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300337,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、真头痛。头痛甚。脑尽痛。手足寒至节。死不治。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3AM9499pTuK', 4, '{"title":"第20300338条・厥病第二十四","description":"<p>5、头痛不可取于腧者。有所击堕。恶血在于内。若肉伤。痛未已。可则刺。不可远取也。头痛不可刺者。大痹为恶。日作者。可令少愈。不可已。头半寒痛。先取手少阳阳明。后取足少阳阳明。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300338,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、头痛不可取于腧者。有所击堕。恶血在于内。若肉伤。痛未已。可则刺。不可远取也。头痛不可刺者。大痹为恶。日作者。可令少愈。不可已。头半寒痛。先取手少阳阳明。后取足少阳阳明。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mVMeyY53lb8', 4, '{"title":"第20300339条・厥病第二十四","description":"<p>6、厥心痛。与背相控。善瘈。如从后触其心。伛偻者。肾心痛也。先取京骨。昆仑。发狂不已。取然谷。厥心痛。腹胀胸满。心尤痛甚。胃心痛也。取之大都。大白。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300339,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、厥心痛。与背相控。善瘈。如从后触其心。伛偻者。肾心痛也。先取京骨。昆仑。发狂不已。取然谷。厥心痛。腹胀胸满。心尤痛甚。胃心痛也。取之大都。大白。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('prX0QvFIObt', 4, '{"title":"第20300340条・厥病第二十四","description":"<p>7、厥心痛。痛如以锥针刺其心。心痛甚者。脾心痛也。取之然谷。太溪。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300340,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '7、厥心痛。痛如以锥针刺其心。心痛甚者。脾心痛也。取之然谷。太溪。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gILqafyjKfZ', 4, '{"title":"第20300341条・厥病第二十四","description":"<p>8、厥心痛。色苍苍如死状。终日不得太息。肝心痛也。取之行间。太冲。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300341,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '8、厥心痛。色苍苍如死状。终日不得太息。肝心痛也。取之行间。太冲。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hcqdI0D6CCM', 4, '{"title":"第20300342条・厥病第二十四","description":"<p>9、厥心痛。卧若徒居。心痛间。动作。痛益甚。色不变。肺心痛也。取之鱼际。太渊。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300342,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '9、厥心痛。卧若徒居。心痛间。动作。痛益甚。色不变。肺心痛也。取之鱼际。太渊。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dk48BpqlKWT', 4, '{"title":"第20300343条・厥病第二十四","description":"<p>10、真心痛。手足清至节。心痛甚。日发夕死。夕发旦死。心痛不可刺者。中有盛聚。不可取于腧。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300343,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '10、真心痛。手足清至节。心痛甚。日发夕死。夕发旦死。心痛不可刺者。中有盛聚。不可取于腧。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uSr5uwLfctI', 4, '{"title":"第20300344条・厥病第二十四","description":"<p>11、肠中有虫瘕及蛟蛕。皆不可取以小针。心肠痛。憹作痛。肿聚。往来上下行。痛有休止。腹热喜渴涎出者。是蛟蛕也。以手聚按而坚持之。无令得移。以大针刺之。久持之。虫不动。乃出针也。恐腹浓痛。形中上者。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300344,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '11、肠中有虫瘕及蛟蛕。皆不可取以小针。心肠痛。憹作痛。肿聚。往来上下行。痛有休止。腹热喜渴涎出者。是蛟蛕也。以手聚按而坚持之。无令得移。以大针刺之。久持之。虫不动。乃出针也。恐腹浓痛。形中上者。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9QTCG0QwXV6', 4, '{"title":"第20300345条・厥病第二十四","description":"<p>12、耳聋无闻。取耳中。耳鸣。取耳前动脉。耳痛不可刺者。耳中有脓。若有干聆聊。耳无闻也。耳聋取手小指次指爪甲上与肉交者。先取手。后取足。耳鸣取手中指爪甲上。左取右。右取左。先取手。后取足。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300345,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '12、耳聋无闻。取耳中。耳鸣。取耳前动脉。耳痛不可刺者。耳中有脓。若有干聆聊。耳无闻也。耳聋取手小指次指爪甲上与肉交者。先取手。后取足。耳鸣取手中指爪甲上。左取右。右取左。先取手。后取足。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XFGowHpiERl', 4, '{"title":"第20300346条・厥病第二十四","description":"<p>13、足髀不可举。侧而取之。在枢合中。以员利针。大针不可刺。病注下血。取曲泉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300346,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '13、足髀不可举。侧而取之。在枢合中。以员利针。大针不可刺。病注下血。取曲泉。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BSRsHAaMvlh', 4, '{"title":"第20300347条・厥病第二十四","description":"<p>14、风痹淫砾。病不可已者。足如履冰。时如入汤中。股胫淫砾。烦心头痛。时呕时悗。眩已汗出。久则目眩。悲以喜恐。短气。不乐。不出三年死也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300347,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '14、风痹淫砾。病不可已者。足如履冰。时如入汤中。股胫淫砾。烦心头痛。时呕时悗。眩已汗出。久则目眩。悲以喜恐。短气。不乐。不出三年死也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'rCF9teO6jOw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0VVqWVXUZA5', 4, '{"title":"第20300348条・病本第二十五","description":"<p>1、先病而后逆者。治其本。先逆而后病者。治其本。先寒而后生病者。治其本。先病而后生寒者。治其本。先热而后生病者。治其本。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300348,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、先病而后逆者。治其本。先逆而后病者。治其本。先寒而后生病者。治其本。先病而后生寒者。治其本。先热而后生病者。治其本。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Q66U9K1ZZcd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Er9nqWU1NFb', 4, '{"title":"第20300349条・病本第二十五","description":"<p>2、先泄而后生他病者。治其本。必且调之。乃治其它病。先病而后中满者。治其标。先病后泄者。治其本。先中满而后烦心者。治其本。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300349,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、先泄而后生他病者。治其本。必且调之。乃治其它病。先病而后中满者。治其标。先病后泄者。治其本。先中满而后烦心者。治其本。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Q66U9K1ZZcd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sOFVvodXaDO', 4, '{"title":"第20300350条・病本第二十五","description":"<p>3、有客气。有同气。大小便不利治其标。大小便利。治其本。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300350,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、有客气。有同气。大小便不利治其标。大小便利。治其本。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Q66U9K1ZZcd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9LxezMRnoyo', 4, '{"title":"第20300351条・病本第二十五","description":"<p>4、病发而有余。本而标之。先治其本。后治其标。病发而不足。标而本之。先治其标。后治其本。谨详察间甚。以意调之。间者并行。甚为独行。先小大便不利而后生他病者。治其本也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300351,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、病发而有余。本而标之。先治其本。后治其标。病发而不足。标而本之。先治其标。后治其本。谨详察间甚。以意调之。间者并行。甚为独行。先小大便不利而后生他病者。治其本也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Q66U9K1ZZcd');
