INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wMjhVj3hyTO', 4, '{"title":"第20300376条・杂病第二十六","description":"<p>25、顑痛。刺足阳明曲周动脉。见血。立已。不已。按人迎于经。立已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300376,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '25、顑痛。刺足阳明曲周动脉。见血。立已。不已。按人迎于经。立已。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tn4IPZVYsmm');
