INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lWom5qG2n15', 4, '{"title":"第20300378条・杂病第二十六","description":"<p>27、腹痛。刺脐左右动脉。已刺按之。立已。不已。刺气街。已刺按之。立已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300378,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '27、腹痛。刺脐左右动脉。已刺按之。立已。不已。刺气街。已刺按之。立已。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tn4IPZVYsmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SruMgxEiV6r', 4, '{"title":"第20300379条・杂病第二十六","description":"<p>28、痿厥为四末束悗。乃疾解之。日二。不仁者。十日而知。无休。病已止。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300379,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '28、痿厥为四末束悗。乃疾解之。日二。不仁者。十日而知。无休。病已止。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tn4IPZVYsmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VYlApqm4jc2', 4, '{"title":"第20300380条・杂病第二十六","description":"<p>29、哕以草刺鼻。嚏。嚏而已。无息。而疾迎引之。立已。大惊之。亦可已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300380,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '29、哕以草刺鼻。嚏。嚏而已。无息。而疾迎引之。立已。大惊之。亦可已。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Tn4IPZVYsmm');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3klIoyAEue2', 4, '{"title":"第20300381条・周痹第二十七","description":"<p>1、黄帝问于岐伯曰。周痹之在身也。上下移徒随脉。其上下左右相应。间不容空。愿闻此痛。在血脉之中邪。将在分肉之间乎。何以致是。其痛之移也。间不及下针。其慉痛之时。不及定治。而痛已止矣。何道使然。愿闻其故。岐伯答曰。此众痹也。非周痹也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300381,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝问于岐伯曰。周痹之在身也。上下移徒随脉。其上下左右相应。间不容空。愿闻此痛。在血脉之中邪。将在分肉之间乎。何以致是。其痛之移也。间不及下针。其慉痛之时。不及定治。而痛已止矣。何道使然。愿闻其故。岐伯答曰。此众痹也。非周痹也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Qax08RzEdMR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9JteA7qWCBQ', 4, '{"title":"第20300382条・周痹第二十七","description":"<p>2、黄帝曰。愿闻众痹。岐伯对曰。此各在其处。更发更止。更居更起。以右应左。以左应右。非能周也。更发更休也。黄帝曰。善。刺之奈何。岐伯对曰。刺此者。痛虽已止。必刺其处。勿令复起。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300382,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、黄帝曰。愿闻众痹。岐伯对曰。此各在其处。更发更止。更居更起。以右应左。以左应右。非能周也。更发更休也。黄帝曰。善。刺之奈何。岐伯对曰。刺此者。痛虽已止。必刺其处。勿令复起。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Qax08RzEdMR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ED5Sm5LIdvl', 4, '{"title":"第20300383条・周痹第二十七","description":"<p>3、帝曰。善。愿闻周痹何如。岐伯对曰。周痹者。在于血脉之中。随脉以上。随脉以下。不能左右。各当其所。黄帝曰。刺之奈何。岐伯对曰。痛从上下者。先刺其下以过之。后刺其上以脱之。痛从下上者。先刺其上以过之。后刺其下以脱之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300383,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、帝曰。善。愿闻周痹何如。岐伯对曰。周痹者。在于血脉之中。随脉以上。随脉以下。不能左右。各当其所。黄帝曰。刺之奈何。岐伯对曰。痛从上下者。先刺其下以过之。后刺其上以脱之。痛从下上者。先刺其上以过之。后刺其下以脱之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Qax08RzEdMR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('440cATfE8zc', 4, '{"title":"第20300384条・周痹第二十七","description":"<p>4、黄帝曰。善。此痛安生。何因而有名。岐伯对曰。风寒湿气。客于外分肉之间。迫切而为沫。沫得寒则聚。聚则排分肉而分裂也。分裂则痛。痛则神归之。神归之则热。热则痛解。痛解则厥。厥则他痹发。发则如是。帝曰。善。余已得其意矣。此内不在藏。而外未发于皮。独居分肉之间。真气不能周。故名曰周痹。故刺痹者。必先切循其下之六经。视其虚实。及大络之血结而不通。及虚而脉陷空者而调之。熨而通之。其瘈坚转引而行之。黄帝曰。善。余已得其意矣。亦得其事也。九者经巽之理。十二经脉阴阳之病也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300384,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、黄帝曰。善。此痛安生。何因而有名。岐伯对曰。风寒湿气。客于外分肉之间。迫切而为沫。沫得寒则聚。聚则排分肉而分裂也。分裂则痛。痛则神归之。神归之则热。热则痛解。痛解则厥。厥则他痹发。发则如是。帝曰。善。余已得其意矣。此内不在藏。而外未发于皮。独居分肉之间。真气不能周。故名曰周痹。故刺痹者。必先切循其下之六经。视其虚实。及大络之血结而不通。及虚而脉陷空者而调之。熨而通之。其瘈坚转引而行之。黄帝曰。善。余已得其意矣。亦得其事也。九者经巽之理。十二经脉阴阳之病也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'Qax08RzEdMR');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2kJwD4cWhac', 4, '{"title":"第20300385条・口问第二十八","description":"<p>1、黄帝闲居。辟左右而问于岐伯曰。余已闻九针之经。论阴阳逆顺。六经已毕。愿得口问。岐伯避席再拜曰。善乎哉问也。此先师之所口传也。黄帝曰。愿闻口传。岐伯答曰。夫百病之始生也。皆生于风雨寒暑。阴阳喜怒。饮食居处。大惊卒恐。则血气分离。阴阳破败。经络厥绝。脉道不通。阴阳相逆。卫气稽留。经脉虚空。血气不次。乃失其常。论不在经者。请道其方。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300385,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝闲居。辟左右而问于岐伯曰。余已闻九针之经。论阴阳逆顺。六经已毕。愿得口问。岐伯避席再拜曰。善乎哉问也。此先师之所口传也。黄帝曰。愿闻口传。岐伯答曰。夫百病之始生也。皆生于风雨寒暑。阴阳喜怒。饮食居处。大惊卒恐。则血气分离。阴阳破败。经络厥绝。脉道不通。阴阳相逆。卫气稽留。经脉虚空。血气不次。乃失其常。论不在经者。请道其方。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Yyr2qoYkXp', 4, '{"title":"第20300386条・口问第二十八","description":"<p>2、黄帝曰。人之欠者。何气使然。岐伯答曰。卫气昼日行于阳。夜半则行于阴。阴者主夜。夜者卧。阳者主上。阴者主下。故阴气积于下。阳气未尽。阳引而上。阴引而下。阴阳相引。故数欠。阳气尽。阴气盛。则目瞑。阴气尽而阳气盛。则寤矣。泻足少阴。补足太阳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300386,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、黄帝曰。人之欠者。何气使然。岐伯答曰。卫气昼日行于阳。夜半则行于阴。阴者主夜。夜者卧。阳者主上。阴者主下。故阴气积于下。阳气未尽。阳引而上。阴引而下。阴阳相引。故数欠。阳气尽。阴气盛。则目瞑。阴气尽而阳气盛。则寤矣。泻足少阴。补足太阳。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7ipMQ2cDI3T', 4, '{"title":"第20300387条・口问第二十八","description":"<p>3、黄帝曰。人之哕者。何气使然。岐伯曰。谷入于胃。胃气上注于肺。今有故寒气与新谷气。俱还入于胃。新故相乱。真邪相攻。气并相逆。复出于胃。故为哕。补手太阴。泻足少阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300387,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、黄帝曰。人之哕者。何气使然。岐伯曰。谷入于胃。胃气上注于肺。今有故寒气与新谷气。俱还入于胃。新故相乱。真邪相攻。气并相逆。复出于胃。故为哕。补手太阴。泻足少阴。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T7XS20GSygM', 4, '{"title":"第20300388条・口问第二十八","description":"<p>4、黄帝曰。人之唏者。何气使然。岐伯曰。此阴气盛而阳气虚。阴气疾而阳气徐。阴气盛而阳气绝。故为唏。补足太阳。泻足少阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300388,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、黄帝曰。人之唏者。何气使然。岐伯曰。此阴气盛而阳气虚。阴气疾而阳气徐。阴气盛而阳气绝。故为唏。补足太阳。泻足少阴。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Wh7z27Z1GyR', 4, '{"title":"第20300389条・口问第二十八","description":"<p>5、黄帝曰。人之振寒者。何气使然。岐伯曰。寒气客于皮肤。阴气盛。阳气虚。故为振寒寒栗。补诸阳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300389,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、黄帝曰。人之振寒者。何气使然。岐伯曰。寒气客于皮肤。阴气盛。阳气虚。故为振寒寒栗。补诸阳。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tvn6znLVLfv', 4, '{"title":"第20300390条・口问第二十八","description":"<p>6、黄帝曰。人之噫者。何气使然。岐伯曰。寒气客于胃。厥逆从下上散。复出于胃。故为噫。补足太阴阳明。一曰补眉本也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300390,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、黄帝曰。人之噫者。何气使然。岐伯曰。寒气客于胃。厥逆从下上散。复出于胃。故为噫。补足太阴阳明。一曰补眉本也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TaYW3e5wHkF', 4, '{"title":"第20300391条・口问第二十八","description":"<p>7、黄帝曰。人之嚏者。何气使然。岐伯曰。阳气和利。满于心。出于鼻。故为嚏。补足太阳荣眉本。一曰眉上也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300391,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '7、黄帝曰。人之嚏者。何气使然。岐伯曰。阳气和利。满于心。出于鼻。故为嚏。补足太阳荣眉本。一曰眉上也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dvyPTZS0ysc', 4, '{"title":"第20300392条・口问第二十八","description":"<p>8、黄帝曰。人之亸者。何气使然。岐伯曰。胃不实则诸脉虚。诸脉虚则筋脉懈惰。筋脉懈惰则行阴用力。气不能复。故为亸。因其所在。补分肉间。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300392,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '8、黄帝曰。人之亸者。何气使然。岐伯曰。胃不实则诸脉虚。诸脉虚则筋脉懈惰。筋脉懈惰则行阴用力。气不能复。故为亸。因其所在。补分肉间。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oEH3SJj3SJF', 4, '{"title":"第20300393条・口问第二十八","description":"<p>9、黄帝曰。人之哀而泣涕出者。何气使然。岐伯曰。心者。五藏六府之主也。目者。宗脉之所聚也。上液之道也。口鼻者。气之门户也。故悲哀愁忧则心动。心动则五藏六府皆摇。摇则宗脉感。宗脉感则液道开。液道开。故泣涕出焉。液者。所以灌精濡空窍者也。故上液之道开则泣。泣不止则液竭。液竭则精不灌。精不灌则目无所见矣。故命曰夺精。补天柱经侠颈。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300393,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '9、黄帝曰。人之哀而泣涕出者。何气使然。岐伯曰。心者。五藏六府之主也。目者。宗脉之所聚也。上液之道也。口鼻者。气之门户也。故悲哀愁忧则心动。心动则五藏六府皆摇。摇则宗脉感。宗脉感则液道开。液道开。故泣涕出焉。液者。所以灌精濡空窍者也。故上液之道开则泣。泣不止则液竭。液竭则精不灌。精不灌则目无所见矣。故命曰夺精。补天柱经侠颈。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nk9dY38BDdd', 4, '{"title":"第20300394条・口问第二十八","description":"<p>10、黄帝曰。人之太息者。何气使然。岐伯曰。忧思则心系急。心系急则气道约。约则不利。故太息以伸出之。补手少阴心主。足少阳留之也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300394,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '10、黄帝曰。人之太息者。何气使然。岐伯曰。忧思则心系急。心系急则气道约。约则不利。故太息以伸出之。补手少阴心主。足少阳留之也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w8dqAwwnwax', 4, '{"title":"第20300395条・口问第二十八","description":"<p>11、黄帝曰。人之涎下者。何气使然。岐伯曰。饮食者。皆入于胃。胃中有热则虫动。虫动则胃缓。胃缓则廉泉开。故涎下。补足少阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300395,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '11、黄帝曰。人之涎下者。何气使然。岐伯曰。饮食者。皆入于胃。胃中有热则虫动。虫动则胃缓。胃缓则廉泉开。故涎下。补足少阴。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tNuDXT9nyo5', 4, '{"title":"第20300396条・口问第二十八","description":"<p>12、黄帝曰。人之耳中鸣者。何气使然。岐伯曰。耳者。宗脉之所聚也。故胃中空则宗脉虚。虚则下溜。脉有所竭者。故耳鸣。补客主人。手大指爪甲上与肉交者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300396,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '12、黄帝曰。人之耳中鸣者。何气使然。岐伯曰。耳者。宗脉之所聚也。故胃中空则宗脉虚。虚则下溜。脉有所竭者。故耳鸣。补客主人。手大指爪甲上与肉交者也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zBg43ZcwB4v', 4, '{"title":"第20300397条・口问第二十八","description":"<p>13、黄帝曰。人之自啮舌者。何气使然。岐伯曰。此厥逆走上。脉气辈至也。少阴气至则啮舌。少阳气至则啮颊。阳明气至则啮唇矣。视主病者。则补之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300397,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '13、黄帝曰。人之自啮舌者。何气使然。岐伯曰。此厥逆走上。脉气辈至也。少阴气至则啮舌。少阳气至则啮颊。阳明气至则啮唇矣。视主病者。则补之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uMoiHI2ceMF', 4, '{"title":"第20300398条・口问第二十八","description":"<p>14、凡此十二邪者。皆奇邪之走空窍者也。故邪之所在。皆为不足。故上气不足。脑为之不满。耳为之苦鸣。头为之苦倾。目为之眩。中气不足。溲便为之变。肠为之苦鸣。下气不足。则乃为痿厥心悗。补足外踝下留之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300398,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '14、凡此十二邪者。皆奇邪之走空窍者也。故邪之所在。皆为不足。故上气不足。脑为之不满。耳为之苦鸣。头为之苦倾。目为之眩。中气不足。溲便为之变。肠为之苦鸣。下气不足。则乃为痿厥心悗。补足外踝下留之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WINi5ZslaKV', 4, '{"title":"第20300399条・口问第二十八","description":"<p>15、黄帝曰。治之奈何。岐伯曰。肾主为欠。取足少阴。肺主为哕。取手太阴。足少阴。唏者。阴与阳绝。故补足太阳。泻足少阴。振寒者。补诸阳。噫者。补足太阴阳明。嚏者。补足太阳眉本。亸。因其所在。补分肉间。泣出补天柱经侠颈。侠颈者。头中分也。太息。补手少阴。心主。足少阳。留之。涎下补足少阴。耳鸣补客主人。手大指爪甲上与肉交者。自啮舌。视主病者。则补之。目眩头倾。补足外踝下留之。痿厥心悗。刺足大指间上二寸。留之。一曰足外踝下留之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300399,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '15、黄帝曰。治之奈何。岐伯曰。肾主为欠。取足少阴。肺主为哕。取手太阴。足少阴。唏者。阴与阳绝。故补足太阳。泻足少阴。振寒者。补诸阳。噫者。补足太阴阳明。嚏者。补足太阳眉本。亸。因其所在。补分肉间。泣出补天柱经侠颈。侠颈者。头中分也。太息。补手少阴。心主。足少阳。留之。涎下补足少阴。耳鸣补客主人。手大指爪甲上与肉交者。自啮舌。视主病者。则补之。目眩头倾。补足外踝下留之。痿厥心悗。刺足大指间上二寸。留之。一曰足外踝下留之。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'sqbykDzpFko');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T6GZ0gOs33T', 4, '{"title":"第20300400条・师传第二十九","description":"<p>1、黄帝曰。余闻先师。有所心藏。弗着于方。余愿闻而藏之。则而行之。上以治民。下以治身。使百姓无病。上下和亲。德泽下流。子孙无优。传于后世。无有终时。可得闻乎。岐伯曰。远乎哉问也。夫治民与自治。治彼与治此。治小与治大。治国与治家。未有逆而能治之也。夫惟顺而已矣。顺者。非独阴阳脉。论气之逆顺也。百姓人民皆欲顺其志也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300400,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝曰。余闻先师。有所心藏。弗着于方。余愿闻而藏之。则而行之。上以治民。下以治身。使百姓无病。上下和亲。德泽下流。子孙无优。传于后世。无有终时。可得闻乎。岐伯曰。远乎哉问也。夫治民与自治。治彼与治此。治小与治大。治国与治家。未有逆而能治之也。夫惟顺而已矣。顺者。非独阴阳脉。论气之逆顺也。百姓人民皆欲顺其志也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GXR7FCPDkOi', 4, '{"title":"第20300401条・师传第二十九","description":"<p>2、黄帝曰。顺之奈何。岐伯曰。入国问俗。入家问讳。上堂问礼。临病人问所便。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300401,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、黄帝曰。顺之奈何。岐伯曰。入国问俗。入家问讳。上堂问礼。临病人问所便。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tpDBMXKeQjm', 4, '{"title":"第20300402条・师传第二十九","description":"<p>3、黄帝曰。便病人奈何。岐伯曰。夫中热消瘅。则便寒。寒中之属。则便热。胃中热则消谷。令人悬心善饥。脐以上皮热。肠中热。则出黄如糜。脐以下皮寒。胃中寒。则腹胀。肠中寒。则肠鸣飧泄。胃中寒。肠中热。则胀而且泄。胃中热。肠中寒。则疾饮。小腹痛胀。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300402,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、黄帝曰。便病人奈何。岐伯曰。夫中热消瘅。则便寒。寒中之属。则便热。胃中热则消谷。令人悬心善饥。脐以上皮热。肠中热。则出黄如糜。脐以下皮寒。胃中寒。则腹胀。肠中寒。则肠鸣飧泄。胃中寒。肠中热。则胀而且泄。胃中热。肠中寒。则疾饮。小腹痛胀。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('75CteNXq9fc', 4, '{"title":"第20300403条・师传第二十九","description":"<p>4、黄帝曰。胃欲寒饮。肠欲热饮。两者相逆。便之奈何。且夫王公大人。血食之君。骄恣从欲轻人。而无能禁之。禁之则逆其志。顺之则加其病。便之奈何。治之何先。岐伯曰。人之情。莫不恶死而喜生。告之以其败。语之以其善。导之以其所便。开之以其所苦。虽有无道之人。恶有不听者乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300403,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、黄帝曰。胃欲寒饮。肠欲热饮。两者相逆。便之奈何。且夫王公大人。血食之君。骄恣从欲轻人。而无能禁之。禁之则逆其志。顺之则加其病。便之奈何。治之何先。岐伯曰。人之情。莫不恶死而喜生。告之以其败。语之以其善。导之以其所便。开之以其所苦。虽有无道之人。恶有不听者乎。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KFx7k130KGv', 4, '{"title":"第20300404条・师传第二十九","description":"<p>5、黄帝曰。治之奈何。岐伯曰。春夏先治其标。后治其本。秋冬先治其本。后治其标。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300404,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、黄帝曰。治之奈何。岐伯曰。春夏先治其标。后治其本。秋冬先治其本。后治其标。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Kg6DjAlGoXt', 4, '{"title":"第20300405条・师传第二十九","description":"<p>6、黄帝曰。便其相逆者奈何。岐伯曰。便此者。食饮衣服。亦欲适寒温。寒无凄怆。暑无出汗。食饮者。热无灼灼。寒无沧沧。寒温中适。故气将持。乃不致邪僻也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300405,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、黄帝曰。便其相逆者奈何。岐伯曰。便此者。食饮衣服。亦欲适寒温。寒无凄怆。暑无出汗。食饮者。热无灼灼。寒无沧沧。寒温中适。故气将持。乃不致邪僻也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iJmYOyIiqYj', 4, '{"title":"第20300406条・师传第二十九","description":"<p>7、黄帝曰。本藏以身形肢节䐃肉。候五藏六府之大小焉。今夫王公大人。临朝即位之君。而问焉。谁可扪循之。而后答乎。岐伯曰。身形肢节者。藏府之盖也。非面部之阅也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300406,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '7、黄帝曰。本藏以身形肢节䐃肉。候五藏六府之大小焉。今夫王公大人。临朝即位之君。而问焉。谁可扪循之。而后答乎。岐伯曰。身形肢节者。藏府之盖也。非面部之阅也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RAh04cQS1CE', 4, '{"title":"第20300407条・师传第二十九","description":"<p>8、黄帝曰。五藏之气。阅于面者。余已知之矣。以肢节知而阅之。奈何。岐伯曰。五藏六府者。肺为之盖。巨肩陷咽。候见其外。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300407,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '8、黄帝曰。五藏之气。阅于面者。余已知之矣。以肢节知而阅之。奈何。岐伯曰。五藏六府者。肺为之盖。巨肩陷咽。候见其外。黄帝曰。善。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('l0xV24vohYO', 4, '{"title":"第20300408条・师传第二十九","description":"<p>9、岐伯曰。五藏六府。心为之主。缺盆为之道。骷骨有余以候𩩲骬。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300408,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '9、岐伯曰。五藏六府。心为之主。缺盆为之道。骷骨有余以候𩩲骬。黄帝曰。善。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OIMMLxHxFD7', 4, '{"title":"第20300409条・师传第二十九","description":"<p>10、岐伯曰。肝者。主为将。使之候外。欲知坚固。视目小大。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300409,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '10、岐伯曰。肝者。主为将。使之候外。欲知坚固。视目小大。黄帝曰。善。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RurX0TSKBBW', 4, '{"title":"第20300410条・师传第二十九","description":"<p>11、岐伯曰。脾者。主为卫。使之迎粮。视唇舌好恶。以知吉凶。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300410,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '11、岐伯曰。脾者。主为卫。使之迎粮。视唇舌好恶。以知吉凶。黄帝曰。善。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('92FGGkvzpSb', 4, '{"title":"第20300411条・师传第二十九","description":"<p>12、岐伯曰。肾者。主为外。使之远听。视耳好恶。以知其性。黄帝曰。善。愿闻六府之候。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300411,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '12、岐伯曰。肾者。主为外。使之远听。视耳好恶。以知其性。黄帝曰。善。愿闻六府之候。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xx8gkqLPbu9', 4, '{"title":"第20300412条・师传第二十九","description":"<p>13、岐伯曰。六府者。胃为之海。庞骸。大颈。张胸。五谷乃容。鼻隧以长。以候大肠。唇厚。人中长。以候小肠。目下果大。其胆乃横。鼻孔在外。膀胱漏泄。鼻柱中央起。三焦乃约。此所以候六府者也。上下三等。藏安且良矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300412,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '13、岐伯曰。六府者。胃为之海。庞骸。大颈。张胸。五谷乃容。鼻隧以长。以候大肠。唇厚。人中长。以候小肠。目下果大。其胆乃横。鼻孔在外。膀胱漏泄。鼻柱中央起。三焦乃约。此所以候六府者也。上下三等。藏安且良矣。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ZiRq1il3ept');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IzAmkjmTiWY', 4, '{"title":"第20300413条・决气第三十","description":"<p>1、黄帝曰。余闻人有精。气。津。液。血。脉。余意以为一气耳。今乃辨为六名。余不知其所以然。岐伯曰。两神相搏。合而成形。常先身生。是谓精。何谓气。岐伯曰。上焦开发。宣五谷味。熏肤。充身。泽毛。若雾露之溉。是谓气。何谓津。岐伯曰。腠理发泄。汗出溱溱。是谓津。何谓液。岐伯曰。谷入气满。淖泽注于骨。骨属屈伸。泄泽补益脑髓。皮肤润泽。是谓液。何谓血。岐伯曰。中焦受气。取汁变化而赤。是谓血。何谓脉。岐伯曰。壅遏营气。令无所避。是谓脉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300413,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝曰。余闻人有精。气。津。液。血。脉。余意以为一气耳。今乃辨为六名。余不知其所以然。岐伯曰。两神相搏。合而成形。常先身生。是谓精。何谓气。岐伯曰。上焦开发。宣五谷味。熏肤。充身。泽毛。若雾露之溉。是谓气。何谓津。岐伯曰。腠理发泄。汗出溱溱。是谓津。何谓液。岐伯曰。谷入气满。淖泽注于骨。骨属屈伸。泄泽补益脑髓。皮肤润泽。是谓液。何谓血。岐伯曰。中焦受气。取汁变化而赤。是谓血。何谓脉。岐伯曰。壅遏营气。令无所避。是谓脉。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RWBetNoocQ7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4Y3t4R0BJUV', 4, '{"title":"第20300414条・决气第三十","description":"<p>2、黄帝曰。六气有。有余不足。气之多少。脑髓之虚实。血脉之清浊。何以知之。岐伯曰。精脱者。耳聋。气脱者。目不明。津脱者。腠理开。汗大泄。液脱者。骨属屈伸不利。色夭。脑髓消。胫痹。耳数鸣。血脱者。色白。夭然不泽。其脉空虚。此其候也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300414,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、黄帝曰。六气有。有余不足。气之多少。脑髓之虚实。血脉之清浊。何以知之。岐伯曰。精脱者。耳聋。气脱者。目不明。津脱者。腠理开。汗大泄。液脱者。骨属屈伸不利。色夭。脑髓消。胫痹。耳数鸣。血脱者。色白。夭然不泽。其脉空虚。此其候也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RWBetNoocQ7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CmAFijtHO7m', 4, '{"title":"第20300415条・决气第三十","description":"<p>3、黄帝曰。六气者。贵贱何如。岐伯曰。六气者。各有部主也。其贵贱善恶。可为常主。然五谷与胃为大海也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300415,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、黄帝曰。六气者。贵贱何如。岐伯曰。六气者。各有部主也。其贵贱善恶。可为常主。然五谷与胃为大海也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RWBetNoocQ7');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nG1Eh5kzmH5', 4, '{"title":"第20300416条・肠胃第三十一","description":"<p>1、黄帝问于伯高曰。余愿闻六府传谷者。肠胃之大小长短。受谷之多少奈何。伯高曰。请尽言之。谷所从出入浅深远近长短之度。唇至齿长九分。口广二寸半。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十两。广一寸半。至胃长一尺六寸。胃纡曲屈。伸之。长二尺六寸。大一尺五寸。径五寸。大容三斗五升。小肠后附脊。左环回日迭积。其注于回肠者。外附于脐上。回运环十六曲。大二寸半。径八分分之少半。长三丈三尺。回肠当脐左环。回周叶积而下。回运还反十六曲。大四寸。径一寸寸之少半。长二丈一尺。广肠传脊。以受回肠。左环叶脊上下。辟大八寸。径二寸寸之大半。长二尺八寸。肠胃所入至所出。长六丈四寸四分。回曲环反。三十二曲也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300416,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝问于伯高曰。余愿闻六府传谷者。肠胃之大小长短。受谷之多少奈何。伯高曰。请尽言之。谷所从出入浅深远近长短之度。唇至齿长九分。口广二寸半。齿以后至会厌。深三寸半。大容五合。舌重十两。长七寸。广二寸半。咽门重十两。广一寸半。至胃长一尺六寸。胃纡曲屈。伸之。长二尺六寸。大一尺五寸。径五寸。大容三斗五升。小肠后附脊。左环回日迭积。其注于回肠者。外附于脐上。回运环十六曲。大二寸半。径八分分之少半。长三丈三尺。回肠当脐左环。回周叶积而下。回运还反十六曲。大四寸。径一寸寸之少半。长二丈一尺。广肠传脊。以受回肠。左环叶脊上下。辟大八寸。径二寸寸之大半。长二尺八寸。肠胃所入至所出。长六丈四寸四分。回曲环反。三十二曲也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '2KctBlg72fX');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o6sa4m7uFDB', 4, '{"title":"第20300417条・平人绝谷第三十二","description":"<p>1、黄帝曰。愿闻人之不食。七日而死。何也。伯高曰。臣请言其故。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300417,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝曰。愿闻人之不食。七日而死。何也。伯高曰。臣请言其故。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5a3Bcyco3qU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xtw5qCU0v4v', 4, '{"title":"第20300418条・平人绝谷第三十二","description":"<p>2、胃大一尺五寸。径五寸。长二尺六寸。横屈受水谷三斗五升。其中之谷。常留二斗。水一斗五升而满。上焦泄气。出其精微。慓悍滑疾。下焦下溉诸肠。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300418,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、胃大一尺五寸。径五寸。长二尺六寸。横屈受水谷三斗五升。其中之谷。常留二斗。水一斗五升而满。上焦泄气。出其精微。慓悍滑疾。下焦下溉诸肠。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5a3Bcyco3qU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nl5RA5mR9nK', 4, '{"title":"第20300419条・平人绝谷第三十二","description":"<p>3、小肠大二寸半。径八分分之少半。长三丈二尺。受谷二斗四升。水六升三合合之大半。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300419,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、小肠大二寸半。径八分分之少半。长三丈二尺。受谷二斗四升。水六升三合合之大半。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5a3Bcyco3qU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6j4UOTMElAk', 4, '{"title":"第20300420条・平人绝谷第三十二","description":"<p>4、回肠大四寸。径一寸寸之少半。长二丈一尺。受谷一斗。水七升半。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300420,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、回肠大四寸。径一寸寸之少半。长二丈一尺。受谷一斗。水七升半。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5a3Bcyco3qU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y5wAe5vLwhC', 4, '{"title":"第20300421条・平人绝谷第三十二","description":"<p>5、广肠大八寸。径二寸寸之大半。长二尺八寸。受谷九升三合八分合之一。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300421,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、广肠大八寸。径二寸寸之大半。长二尺八寸。受谷九升三合八分合之一。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5a3Bcyco3qU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hObCGqSlrtm', 4, '{"title":"第20300422条・平人绝谷第三十二","description":"<p>6、肠胃之长。凡五丈八尺四寸。受水谷九斗二升一合合之大半。此肠胃所受水谷之数也。平人则不然。胃满则肠虚。肠满则胃虚。更虚更满。故气得上下。五藏安定。血脉和利。精神乃居。故神者。水谷之精气也。故肠胃之中。当留谷二斗。水一斗五升。故平人日再后。后二升半。一日中五升。七日五七三斗五升。而留水谷尽矣。故平人不食饮七日而死者。小谷精气津液皆尽故也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300422,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、肠胃之长。凡五丈八尺四寸。受水谷九斗二升一合合之大半。此肠胃所受水谷之数也。平人则不然。胃满则肠虚。肠满则胃虚。更虚更满。故气得上下。五藏安定。血脉和利。精神乃居。故神者。水谷之精气也。故肠胃之中。当留谷二斗。水一斗五升。故平人日再后。后二升半。一日中五升。七日五七三斗五升。而留水谷尽矣。故平人不食饮七日而死者。小谷精气津液皆尽故也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '5a3Bcyco3qU');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fAr6lGctfrB', 4, '{"title":"第20300423条・海论第三十三","description":"<p>1、黄帝问于岐伯曰。余闻刺法于夫子。夫子之所言。不离于营卫血气。夫十二经脉者。内属于府藏。外络于肢节。夫子乃合之于四海乎。岐伯答曰。人亦有四海。十二经水。经水者。皆注于海。海有东西南北。命曰四海。黄帝曰。以人应之奈何。岐伯曰。人有髓海。有血海。有气海。有水谷之海。凡此四者。以应四海也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300423,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '1、黄帝问于岐伯曰。余闻刺法于夫子。夫子之所言。不离于营卫血气。夫十二经脉者。内属于府藏。外络于肢节。夫子乃合之于四海乎。岐伯答曰。人亦有四海。十二经水。经水者。皆注于海。海有东西南北。命曰四海。黄帝曰。以人应之奈何。岐伯曰。人有髓海。有血海。有气海。有水谷之海。凡此四者。以应四海也。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '8fcCrgADmrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HJJPHZIUdpu', 4, '{"title":"第20300424条・海论第三十三","description":"<p>2、黄帝曰。远乎者。夫子之合人天地四海也。愿闻应之奈何。岐伯曰。必先明知阴阳表里荥输所在。四海定矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300424,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2、黄帝曰。远乎者。夫子之合人天地四海也。愿闻应之奈何。岐伯曰。必先明知阴阳表里荥输所在。四海定矣。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '8fcCrgADmrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('umGCdHfDETq', 4, '{"title":"第20300425条・海论第三十三","description":"<p>3、黄帝曰。定之奈何。岐伯曰。胃者水谷之海。其输上在气街$a{冲}。下至三里。冲脉者。为十二经之海。其输上在于大杼。下出于巨虚之上下廉。膻中者。为气之海。其输上在于柱骨之上下。前在于人迎。脑为髓之海。其输上在于其盖。下在风府。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300425,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '3、黄帝曰。定之奈何。岐伯曰。胃者水谷之海。其输上在气街$a{冲}。下至三里。冲脉者。为十二经之海。其输上在于大杼。下出于巨虚之上下廉。膻中者。为气之海。其输上在于柱骨之上下。前在于人迎。脑为髓之海。其输上在于其盖。下在风府。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '8fcCrgADmrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('11gQWySVRVB', 4, '{"title":"第20300426条・海论第三十三","description":"<p>4、黄帝曰。凡此四海者。何利何害。何生何败。岐伯曰。得顺者生。得逆者败。知调者利。不知调者害。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300426,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '4、黄帝曰。凡此四海者。何利何害。何生何败。岐伯曰。得顺者生。得逆者败。知调者利。不知调者害。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '8fcCrgADmrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PKLcq2tftjd', 4, '{"title":"第20300427条・海论第三十三","description":"<p>5、黄帝曰。四海之逆顺奈何。岐伯曰。气海有余者。气满胸中。悗息面赤。气海不足。则气少不足以言。血海有余。则常想其身大。怫然不知其所病。血海不足。亦常想其身小。狭然不知其所病。水谷之海有余。则腹满。水谷之海不足。则饥不受谷食。髓海有余。则轻劲多力。自过其度。髓海不足。则脑转耳鸣。胫酸眩冒。目无所见。懈怠安卧。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300427,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '5、黄帝曰。四海之逆顺奈何。岐伯曰。气海有余者。气满胸中。悗息面赤。气海不足。则气少不足以言。血海有余。则常想其身大。怫然不知其所病。血海不足。亦常想其身小。狭然不知其所病。水谷之海有余。则腹满。水谷之海不足。则饥不受谷食。髓海有余。则轻劲多力。自过其度。髓海不足。则脑转耳鸣。胫酸眩冒。目无所见。懈怠安卧。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '8fcCrgADmrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TMLFU5v8BEw', 4, '{"title":"第20300428条・海论第三十三","description":"<p>6、黄帝曰。余已闻逆顺。调之奈何。岐伯曰。审守其俞。而调其虚实。无犯其害。顺者得复。逆者必败。黄帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300428,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '2024-09-26T13:54:46.000Z', '6、黄帝曰。余已闻逆顺。调之奈何。岐伯曰。审守其俞。而调其虚实。无犯其害。顺者得复。逆者必败。黄帝曰。善。', '2024-09-26T13:54:46.000Z', 1, NULL, 'ghBqURJwurj', 'section', '8fcCrgADmrr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TJR206g2h2G', 4, '{"title":"第20300429条・五乱第三十四","description":"<p>1、黄帝曰。经脉十二者。别为五行。分为四时。何失而乱。何得而治。岐伯曰。五行有序。四时有分。相顺则治。相逆则乱。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300429,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。经脉十二者。别为五行。分为四时。何失而乱。何得而治。岐伯曰。五行有序。四时有分。相顺则治。相逆则乱。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'x20cYSBjPKQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('db6X117V6mZ', 4, '{"title":"第20300430条・五乱第三十四","description":"<p>2、黄帝曰。何谓相顺。岐伯曰。经脉十二者。以应十二月。十二月者。分为四时。四时者。春秋冬夏。其气各异。营卫相随。阴阳已知。清浊不相干。如是则顺之而治。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300430,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。何谓相顺。岐伯曰。经脉十二者。以应十二月。十二月者。分为四时。四时者。春秋冬夏。其气各异。营卫相随。阴阳已知。清浊不相干。如是则顺之而治。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'x20cYSBjPKQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M3OxNvdsNr7', 4, '{"title":"第20300431条・五乱第三十四","description":"<p>3、黄帝曰。何为逆而乱。岐伯曰。清气在阴。浊气在阳。营气顺脉。卫气逆行。清浊相干。乱于胸中。是谓大悗。故气乱于心。则烦心密嘿。俛首静伏。乱于肺。则俛仰喘喝。接手以呼。乱于肠胃。是为霍乱。乱于臂胫。则为四厥。乱于头。则为厥逆。头重眩仆。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300431,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。何为逆而乱。岐伯曰。清气在阴。浊气在阳。营气顺脉。卫气逆行。清浊相干。乱于胸中。是谓大悗。故气乱于心。则烦心密嘿。俛首静伏。乱于肺。则俛仰喘喝。接手以呼。乱于肠胃。是为霍乱。乱于臂胫。则为四厥。乱于头。则为厥逆。头重眩仆。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'x20cYSBjPKQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QZTiIETQROC', 4, '{"title":"第20300432条・五乱第三十四","description":"<p>4、黄帝曰。五乱者。刺之有道乎。岐伯曰。有道以来。有道以去。审知其道。是谓身宝。黄帝曰。善。愿闻其道。岐伯曰。气在于心者。取之手少阴心主之俞。气在于肺者。取之手太阴荥。足少阴俞。气在于肠胃者。取之足太阴阳明。不下者。取之三里。气在于头者。取之天柱大杼。不知。取足太阳荥俞。气在于臂足。取之先去血脉。后取其阳明少阳之荥俞。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300432,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。五乱者。刺之有道乎。岐伯曰。有道以来。有道以去。审知其道。是谓身宝。黄帝曰。善。愿闻其道。岐伯曰。气在于心者。取之手少阴心主之俞。气在于肺者。取之手太阴荥。足少阴俞。气在于肠胃者。取之足太阴阳明。不下者。取之三里。气在于头者。取之天柱大杼。不知。取足太阳荥俞。气在于臂足。取之先去血脉。后取其阳明少阳之荥俞。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'x20cYSBjPKQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QEMS2ClLtHf', 4, '{"title":"第20300433条・五乱第三十四","description":"<p>5、黄帝曰。补泻奈何。岐伯曰。徐入徐出。谓之导气。补泻无形。谓之同精。是非有余不足也。乱气之相逆也。黄帝曰。允乎哉道。明乎哉论。请着之玉版。命曰治乱也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300433,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、黄帝曰。补泻奈何。岐伯曰。徐入徐出。谓之导气。补泻无形。谓之同精。是非有余不足也。乱气之相逆也。黄帝曰。允乎哉道。明乎哉论。请着之玉版。命曰治乱也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'x20cYSBjPKQ');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W41KcGI3ux2', 4, '{"title":"第20300434条・胀论第三十五","description":"<p>1、黄帝曰。脉之应于寸口。如何而胀。岐伯曰。其脉大坚以涩者。胀也。黄帝曰。何以知藏府之胀也。岐伯曰。阴为藏。阳为府。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300434,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。脉之应于寸口。如何而胀。岐伯曰。其脉大坚以涩者。胀也。黄帝曰。何以知藏府之胀也。岐伯曰。阴为藏。阳为府。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KvWn1MU29TG', 4, '{"title":"第20300435条・胀论第三十五","description":"<p>2、黄帝曰。夫气之令人胀也。在于血脉之中耶。藏府之内乎。岐伯曰。三者皆存焉。然非胀之舍也。黄帝曰。愿闻胀之舍。岐伯曰。夫胀者。皆在于藏府之外。排藏府而郭胸胁。胀皮肤。故命曰胀。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300435,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。夫气之令人胀也。在于血脉之中耶。藏府之内乎。岐伯曰。三者皆存焉。然非胀之舍也。黄帝曰。愿闻胀之舍。岐伯曰。夫胀者。皆在于藏府之外。排藏府而郭胸胁。胀皮肤。故命曰胀。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gj52yzF1Ont', 4, '{"title":"第20300436条・胀论第三十五","description":"<p>3、黄帝曰。藏府之在胸胁腹里之内也。若匣匮之藏禁器也。名有次舍。异名而同处。一域之中。其气各异。愿闻其故。黄帝曰。未解其意。再问。岐伯曰。夫胸腹。藏府之郭也。膻中者。心主之宫城也。胃者。太仓也。咽喉。小肠者。传送也。胃之五窍者。闾里门户也。廉泉。玉英者。津液之道也。故五藏六府者。各有畔界。其病各有形状。营气循脉。卫气逆为脉胀。卫气并脉循分为肤胀。三里而泻。近者一下。远者三下。无问虚实。工在疾泻。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300436,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。藏府之在胸胁腹里之内也。若匣匮之藏禁器也。名有次舍。异名而同处。一域之中。其气各异。愿闻其故。黄帝曰。未解其意。再问。岐伯曰。夫胸腹。藏府之郭也。膻中者。心主之宫城也。胃者。太仓也。咽喉。小肠者。传送也。胃之五窍者。闾里门户也。廉泉。玉英者。津液之道也。故五藏六府者。各有畔界。其病各有形状。营气循脉。卫气逆为脉胀。卫气并脉循分为肤胀。三里而泻。近者一下。远者三下。无问虚实。工在疾泻。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kZChwLy7iBN', 4, '{"title":"第20300437条・胀论第三十五","description":"<p>4、黄帝曰。愿闻胀形。岐伯曰。夫心胀者烦心短气。卧不安。肺胀者。虚满而喘咳。肝胀者。胁下满而痛引小腹。脾胀者。善秽。四肢烦俛。体重不能胜衣。卧不安。肾胀者。腹满引背央央然。腰髀痛。六府胀。胃胀者。腹满。胃脘痛。鼻闻焦臭。妨于食。大便难。大肠胀者。肠鸣而痛濯濯。冬日重感于寒。则餐泄不化。小肠胀者。少腹慎胀。引腰而痛。膀胱胀者。少腹而气癃。三焦胀者。气满于皮肤中。轻轻然而不坚。胆胀者。胁下痛胀。口中苦。善太息。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300437,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。愿闻胀形。岐伯曰。夫心胀者烦心短气。卧不安。肺胀者。虚满而喘咳。肝胀者。胁下满而痛引小腹。脾胀者。善秽。四肢烦俛。体重不能胜衣。卧不安。肾胀者。腹满引背央央然。腰髀痛。六府胀。胃胀者。腹满。胃脘痛。鼻闻焦臭。妨于食。大便难。大肠胀者。肠鸣而痛濯濯。冬日重感于寒。则餐泄不化。小肠胀者。少腹慎胀。引腰而痛。膀胱胀者。少腹而气癃。三焦胀者。气满于皮肤中。轻轻然而不坚。胆胀者。胁下痛胀。口中苦。善太息。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TlQm3nf3uFJ', 4, '{"title":"第20300438条・胀论第三十五","description":"<p>5、凡此诸胀者。其道在一。明知逆顺。针数不失。泻虚补实。神去其室。致邪失正。真不可定。粗之所败。谓之天命。补虚泻实。神归其室。久塞其空。谓之良工。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300438,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、凡此诸胀者。其道在一。明知逆顺。针数不失。泻虚补实。神去其室。致邪失正。真不可定。粗之所败。谓之天命。补虚泻实。神归其室。久塞其空。谓之良工。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('r5FPIfTMYBz', 4, '{"title":"第20300439条・胀论第三十五","description":"<p>6、黄帝曰。胀者焉生。何因而有。岐伯曰。卫气之在身也。常然并脉。循分肉。行有逆顺。阴阳相随。乃得天和。五藏更始。四时循序。五谷乃化。然后厥气在下。营卫留止。寒气逆上。真邪相攻。两气相搏。乃合为胀也。黄帝曰。善。何以解惑。岐伯曰。合之于真。三合而得。帝曰。善。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300439,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、黄帝曰。胀者焉生。何因而有。岐伯曰。卫气之在身也。常然并脉。循分肉。行有逆顺。阴阳相随。乃得天和。五藏更始。四时循序。五谷乃化。然后厥气在下。营卫留止。寒气逆上。真邪相攻。两气相搏。乃合为胀也。黄帝曰。善。何以解惑。岐伯曰。合之于真。三合而得。帝曰。善。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LYrqKKSsuIj', 4, '{"title":"第20300440条・胀论第三十五","description":"<p>7、黄帝问于岐伯曰。胀论言无问虚实。工在疾泻。近者一下。远者三下。今有其三而不下者。其过焉在。岐伯对曰。此言陷于肉肓。而中气穴者也。不中气穴。则气内闭。针不陷肓。则气不行。上越中肉。则卫气相乱。阴阳相逐。其于胀也。当泻不泻。气故不下。三而不下。必更其道。气下乃止。不下复始。可以万全。乌有殆者乎。其于胀也。必审其弥。当泻则泻。当补则补。如鼓应桴。恶有不下者乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300440,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、黄帝问于岐伯曰。胀论言无问虚实。工在疾泻。近者一下。远者三下。今有其三而不下者。其过焉在。岐伯对曰。此言陷于肉肓。而中气穴者也。不中气穴。则气内闭。针不陷肓。则气不行。上越中肉。则卫气相乱。阴阳相逐。其于胀也。当泻不泻。气故不下。三而不下。必更其道。气下乃止。不下复始。可以万全。乌有殆者乎。其于胀也。必审其弥。当泻则泻。当补则补。如鼓应桴。恶有不下者乎。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'GDJ85L1LCs0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LI1M2jVae03', 4, '{"title":"第20300441条・五癃津液别第三十六","description":"<p>1、黄帝问于岐伯曰。水谷入于口。输于肠胃。其液别为五。天寒衣薄。则为溺与气。天热衣厚则为汗。悲哀气并则为泣。中热胃缓则为唾。邪气内逆。则气为之闭塞而不行。不行则为水胀。余知其然也。不知其何由生。愿闻其道。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300441,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝问于岐伯曰。水谷入于口。输于肠胃。其液别为五。天寒衣薄。则为溺与气。天热衣厚则为汗。悲哀气并则为泣。中热胃缓则为唾。邪气内逆。则气为之闭塞而不行。不行则为水胀。余知其然也。不知其何由生。愿闻其道。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k0iYZ0xphME', 4, '{"title":"第20300442条・五癃津液别第三十六","description":"<p>2、岐伯曰。水谷皆入于口。其味有五。各注其海。津液各走其道。故三焦出气。以温肌肉。充皮肤。为其津。其流而不行者为液。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300442,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、岐伯曰。水谷皆入于口。其味有五。各注其海。津液各走其道。故三焦出气。以温肌肉。充皮肤。为其津。其流而不行者为液。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vBOcmyQLEqm', 4, '{"title":"第20300443条・五癃津液别第三十六","description":"<p>3、天暑衣厚则腠理开。故汗出。寒留于分肉之间。聚沫则为痛。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300443,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、天暑衣厚则腠理开。故汗出。寒留于分肉之间。聚沫则为痛。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i5tzM8iWzM6', 4, '{"title":"第20300444条・五癃津液别第三十六","description":"<p>4、天寒则腠理闭。气湿不行。水下留于膀胱。则为溺与气。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300444,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、天寒则腠理闭。气湿不行。水下留于膀胱。则为溺与气。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HFLukYX8OWz', 4, '{"title":"第20300445条・五癃津液别第三十六","description":"<p>5、五藏六府。心为之主。耳为之听。目为之候。肺为之相。肝为之将。脾为之卫。肾为之主外。故五藏六府之津液。尽上渗于目。心悲气并。则心系急。心系急则肺举。肺举则液上溢。夫心系与肺。不能常举。乍上乍下。故欬而泣出矣。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300445,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、五藏六府。心为之主。耳为之听。目为之候。肺为之相。肝为之将。脾为之卫。肾为之主外。故五藏六府之津液。尽上渗于目。心悲气并。则心系急。心系急则肺举。肺举则液上溢。夫心系与肺。不能常举。乍上乍下。故欬而泣出矣。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g7hKvOUb38l', 4, '{"title":"第20300446条・五癃津液别第三十六","description":"<p>6、中热则胃中消谷。消谷则虫上下作。肠胃充郭。故胃缓。胃缓则气逆。故唾出。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300446,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、中热则胃中消谷。消谷则虫上下作。肠胃充郭。故胃缓。胃缓则气逆。故唾出。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OQ6jxXnWgcR', 4, '{"title":"第20300447条・五癃津液别第三十六","description":"<p>7、五谷之津液。和合而为膏者。内渗入于骨空。补益脑髓。而下流于阴股。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300447,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、五谷之津液。和合而为膏者。内渗入于骨空。补益脑髓。而下流于阴股。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BE7pTPYlZSX', 4, '{"title":"第20300448条・五癃津液别第三十六","description":"<p>8、阴阳不和。则使液溢而下流于阴。髓液皆减而下。下过度则虚。虚。故腰背痛而胫酸。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300448,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '8、阴阳不和。则使液溢而下流于阴。髓液皆减而下。下过度则虚。虚。故腰背痛而胫酸。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6g3sUuMmP1v', 4, '{"title":"第20300449条・五癃津液别第三十六","description":"<p>9、阴阳气道不通。四海闭塞。三焦不泻。津液不化。水谷并行肠胃之中。别于回肠。留于下焦。不得渗膀胱。则下焦胀。水溢则为水胀。此津液五别之逆顺也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300449,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '9、阴阳气道不通。四海闭塞。三焦不泻。津液不化。水谷并行肠胃之中。别于回肠。留于下焦。不得渗膀胱。则下焦胀。水溢则为水胀。此津液五别之逆顺也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'StptP8Vl4Ki');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VkmEInQz6u8', 4, '{"title":"第20300450条・五阅五使第三十七","description":"<p>1、黄帝问于岐伯曰。余闻刺有五官五阅。以观五气。五气者。五藏之使也。五时之副也。愿闻其五使当安出。岐伯曰。五官者。五藏之阅也。黄帝曰。愿闻其所出。令可为常。岐伯曰。脉出于气口。色见于明堂。五色更出。以应五时。各如其常。经气入藏。必当治理。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300450,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝问于岐伯曰。余闻刺有五官五阅。以观五气。五气者。五藏之使也。五时之副也。愿闻其五使当安出。岐伯曰。五官者。五藏之阅也。黄帝曰。愿闻其所出。令可为常。岐伯曰。脉出于气口。色见于明堂。五色更出。以应五时。各如其常。经气入藏。必当治理。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'BgT9FMykvAd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4DiBZq3mTXE', 4, '{"title":"第20300451条・五阅五使第三十七","description":"<p>2、帝曰。善。五色独决于明堂乎。岐伯曰。五官已辨。阙庭必张。乃立明堂。明堂广大。蕃蔽见外。方壁高基。引垂居外。五色乃治。平搏广大。寿中百岁。见此者。刺之必已。如是之人者。血气有余。肌肉坚致。故可苦以针。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300451,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、帝曰。善。五色独决于明堂乎。岐伯曰。五官已辨。阙庭必张。乃立明堂。明堂广大。蕃蔽见外。方壁高基。引垂居外。五色乃治。平搏广大。寿中百岁。见此者。刺之必已。如是之人者。血气有余。肌肉坚致。故可苦以针。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'BgT9FMykvAd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SDq2R3AnLOr', 4, '{"title":"第20300452条・五阅五使第三十七","description":"<p>3、黄帝曰。愿闻五官。岐伯曰。鼻者。肺之官也。目者。肝之官也。口唇者。脾之官也。舌者。心之官也。耳者。肾之官也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300452,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。愿闻五官。岐伯曰。鼻者。肺之官也。目者。肝之官也。口唇者。脾之官也。舌者。心之官也。耳者。肾之官也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'BgT9FMykvAd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PTC7IO86Stz', 4, '{"title":"第20300453条・五阅五使第三十七","description":"<p>4、黄帝曰。以官何候。岐伯曰。以候五藏。故肺病者。喘息鼻张。肝病者。眦青。脾病者。唇黄。心病者。舌卷短。颧赤。肾病者。颧与颜黑。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300453,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。以官何候。岐伯曰。以候五藏。故肺病者。喘息鼻张。肝病者。眦青。脾病者。唇黄。心病者。舌卷短。颧赤。肾病者。颧与颜黑。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'BgT9FMykvAd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('55Tv2w1UxVW', 4, '{"title":"第20300454条・五阅五使第三十七","description":"<p>5、黄帝曰。五脉安出。五色安见。其常色殆者如何。岐伯曰。五官不辨。阙庭不张。小其明堂。蕃蔽不见。又埤其墙。墙下无基。垂角去外。如是者。虽平常殆。况加疾哉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300454,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、黄帝曰。五脉安出。五色安见。其常色殆者如何。岐伯曰。五官不辨。阙庭不张。小其明堂。蕃蔽不见。又埤其墙。墙下无基。垂角去外。如是者。虽平常殆。况加疾哉。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'BgT9FMykvAd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oMR7wPykbQS', 4, '{"title":"第20300455条・五阅五使第三十七","description":"<p>6、黄帝曰。五色之见于明堂。以观五藏之气。左右高下。各有形乎。岐伯曰。藏府之在中也。各以次舍。左右上下。各如其度也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300455,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、黄帝曰。五色之见于明堂。以观五藏之气。左右高下。各有形乎。岐伯曰。藏府之在中也。各以次舍。左右上下。各如其度也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'BgT9FMykvAd');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p4lbS7r7vbo', 4, '{"title":"第20300456条・逆顺肥瘦第三十八","description":"<p>1、黄帝问于岐伯曰。余闻针道于夫子。众多毕悉矣。夫子之道。应若失。而据未有坚然者也。夫子之问学熟乎。将审察于物而心生之乎。岐伯曰。人之为道者。上合于天。下合于地。中合于人事。必有明法。以起度数。法式检押。乃后可传焉。故匠人不能释尺寸而意短长。废绳墨而起平水也。工人不能置规而为圆。去矩而为方。知用此者。固自然之物。易用之教。逆顺之常也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300456,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝问于岐伯曰。余闻针道于夫子。众多毕悉矣。夫子之道。应若失。而据未有坚然者也。夫子之问学熟乎。将审察于物而心生之乎。岐伯曰。人之为道者。上合于天。下合于地。中合于人事。必有明法。以起度数。法式检押。乃后可传焉。故匠人不能释尺寸而意短长。废绳墨而起平水也。工人不能置规而为圆。去矩而为方。知用此者。固自然之物。易用之教。逆顺之常也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gREBA49gI2B', 4, '{"title":"第20300457条・逆顺肥瘦第三十八","description":"<p>2、黄帝曰。愿闻自然奈何。岐伯曰。临深决水。不用功力。而水可竭也。循拙决冲。而经可通也。此言气之滑涩。血水清浊。行之逆顺也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300457,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。愿闻自然奈何。岐伯曰。临深决水。不用功力。而水可竭也。循拙决冲。而经可通也。此言气之滑涩。血水清浊。行之逆顺也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lz5FVE06Trk', 4, '{"title":"第20300458条・逆顺肥瘦第三十八","description":"<p>3、黄帝曰。愿闻人之白黑肥瘦小长。各有数乎。岐伯曰。年质壮大。血气充盈。肤革坚固。因加以邪。刺此者。深而留之。此肥人也。广肩腋项。肉薄厚皮而黑色。唇临临然。其血黑以浊。其气涩以迟。其为人也。贪于取与。刺此者。深而留之。多益其数也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300458,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。愿闻人之白黑肥瘦小长。各有数乎。岐伯曰。年质壮大。血气充盈。肤革坚固。因加以邪。刺此者。深而留之。此肥人也。广肩腋项。肉薄厚皮而黑色。唇临临然。其血黑以浊。其气涩以迟。其为人也。贪于取与。刺此者。深而留之。多益其数也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oVxrmyRmqcA', 4, '{"title":"第20300459条・逆顺肥瘦第三十八","description":"<p>4、黄帝曰。刺瘦人奈何。岐伯曰。瘦人者。皮薄色少。肉廉廉然。薄唇轻言。其血清气滑。易脱于气。易损于血。刺此者。浅而疾之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300459,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。刺瘦人奈何。岐伯曰。瘦人者。皮薄色少。肉廉廉然。薄唇轻言。其血清气滑。易脱于气。易损于血。刺此者。浅而疾之。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p4eZExG8c8j', 4, '{"title":"第20300460条・逆顺肥瘦第三十八","description":"<p>5、黄帝曰。刺常人奈何。岐伯曰。视其白黑。各为调之。其端正敦厚者。其血气和调。刺此者。无失常数也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300460,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、黄帝曰。刺常人奈何。岐伯曰。视其白黑。各为调之。其端正敦厚者。其血气和调。刺此者。无失常数也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('roCNqCk6saN', 4, '{"title":"第20300461条・逆顺肥瘦第三十八","description":"<p>6、黄帝曰。刺壮士真骨者。奈何。岐伯曰。刺壮士真骨。坚肉缓节。监监然。此人重则气涩血浊。刺此者。深而留之。多益其数。劲则气滑血清。刺此者。浅而疾之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300461,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、黄帝曰。刺壮士真骨者。奈何。岐伯曰。刺壮士真骨。坚肉缓节。监监然。此人重则气涩血浊。刺此者。深而留之。多益其数。劲则气滑血清。刺此者。浅而疾之。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rYB2VD3SedQ', 4, '{"title":"第20300462条・逆顺肥瘦第三十八","description":"<p>7、黄帝曰。刺婴儿奈何。岐伯曰。婴儿者。其肉脆。血少气弱。刺此者。以豪刺。浅刺而疾拔针。日再可也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300462,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、黄帝曰。刺婴儿奈何。岐伯曰。婴儿者。其肉脆。血少气弱。刺此者。以豪刺。浅刺而疾拔针。日再可也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bvV40Dbmn2m', 4, '{"title":"第20300463条・逆顺肥瘦第三十八","description":"<p>8、黄帝曰。临深决水。奈何。岐伯曰。血清气浊$a{滑}。疾泻之则气竭焉。黄帝曰。循拙决冲。奈何。岐伯曰。血浊气涩。疾泻之。则经可通也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300463,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '8、黄帝曰。临深决水。奈何。岐伯曰。血清气浊$a{滑}。疾泻之则气竭焉。黄帝曰。循拙决冲。奈何。岐伯曰。血浊气涩。疾泻之。则经可通也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Kqd8Qd0tyK2', 4, '{"title":"第20300464条・逆顺肥瘦第三十八","description":"<p>9、黄帝曰。脉行之逆顺。奈何。岐伯曰。手之三阴。从藏走手。手之三阳。从手走头。足之三阳。从头走足。足之三阴。从足走腹。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300464,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '9、黄帝曰。脉行之逆顺。奈何。岐伯曰。手之三阴。从藏走手。手之三阳。从手走头。足之三阳。从头走足。足之三阴。从足走腹。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vakGJaXsMrW', 4, '{"title":"第20300465条・逆顺肥瘦第三十八","description":"<p>10、黄帝曰。少阴之脉独下行。何也。岐伯曰。不然。夫冲脉者。五藏六府之海也。五藏六府皆禀焉。其上者。出于颃颡。渗诸阳。灌诸精。其下者。注少阴之大络。出于气街。循阴股内廉入腘中。伏行骭骨内。下至内踝之后属而别。其下者。并于少阴之经。渗三阴。其前者。伏行出跗属。下循跗。入大指间。渗诸络而温肌肉。故别络结则附上不动。不动则厥。厥则寒矣。黄帝曰。何以明之。岐伯曰。以言导之。切而验之。其非必动。然后仍可明逆顺之行也。黄帝曰。窘乎哉。圣人之为道也。明于日月。微于毫厘。其非夫子。孰能道之也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300465,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '10、黄帝曰。少阴之脉独下行。何也。岐伯曰。不然。夫冲脉者。五藏六府之海也。五藏六府皆禀焉。其上者。出于颃颡。渗诸阳。灌诸精。其下者。注少阴之大络。出于气街。循阴股内廉入腘中。伏行骭骨内。下至内踝之后属而别。其下者。并于少阴之经。渗三阴。其前者。伏行出跗属。下循跗。入大指间。渗诸络而温肌肉。故别络结则附上不动。不动则厥。厥则寒矣。黄帝曰。何以明之。岐伯曰。以言导之。切而验之。其非必动。然后仍可明逆顺之行也。黄帝曰。窘乎哉。圣人之为道也。明于日月。微于毫厘。其非夫子。孰能道之也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'H0loEkH3tqB');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Ls9rYgcrBe', 4, '{"title":"第20300466条・血络论第三十九","description":"<p>1、黄帝曰。愿闻其奇邪而不在经者。岐伯曰。血络是也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300466,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。愿闻其奇邪而不在经者。岐伯曰。血络是也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('76OpaJuWirk', 4, '{"title":"第20300467条・血络论第三十九","description":"<p>2、黄帝曰。刺血络而仆者。何也。血出而射者。何也。血少黑而浊者。何也。血出清而半为汁者。何也。拔针而肿者。何也。血出若多若少而面色苍苍者。何也。拔针而面色不变而烦悗者。何也。多出血而不动摇者。何也。愿闻其故。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300467,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。刺血络而仆者。何也。血出而射者。何也。血少黑而浊者。何也。血出清而半为汁者。何也。拔针而肿者。何也。血出若多若少而面色苍苍者。何也。拔针而面色不变而烦悗者。何也。多出血而不动摇者。何也。愿闻其故。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ELb8Ix2jopY', 4, '{"title":"第20300468条・血络论第三十九","description":"<p>3、岐伯曰。脉气盛而血虚者。刺之则脱气。脱气则仆。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300468,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、岐伯曰。脉气盛而血虚者。刺之则脱气。脱气则仆。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N8CK7p9jY17', 4, '{"title":"第20300469条・血络论第三十九","description":"<p>4、血气俱盛而阴气多者。其血滑。刺之则射。阳气蓄积。久留而不泻者。其血黑以浊。故不能射。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300469,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、血气俱盛而阴气多者。其血滑。刺之则射。阳气蓄积。久留而不泻者。其血黑以浊。故不能射。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nuCB2aJ4uUW', 4, '{"title":"第20300470条・血络论第三十九","description":"<p>5、新饮而液渗于络。而未合和于血也。故血出而汁别焉。其不新饮者。身中有水。久则为肿。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300470,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、新饮而液渗于络。而未合和于血也。故血出而汁别焉。其不新饮者。身中有水。久则为肿。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o14nsOnmr8W', 4, '{"title":"第20300471条・血络论第三十九","description":"<p>6、阴气积于阳。其气因于络。故刺之血未出而气先行。故肿。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300471,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、阴气积于阳。其气因于络。故刺之血未出而气先行。故肿。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IvqsxB91mhS', 4, '{"title":"第20300472条・血络论第三十九","description":"<p>7、阴阳之气。其新相得而未和合。因而泻之。则阴阳俱脱。表里相离。故脱色而苍苍然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300472,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、阴阳之气。其新相得而未和合。因而泻之。则阴阳俱脱。表里相离。故脱色而苍苍然。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CwpGrDbk4fL', 4, '{"title":"第20300473条・血络论第三十九","description":"<p>8、刺之血出多。色不变而烦悗者。刺络而虚经。虚经之属于阴者。阴脱。故烦悗。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300473,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '8、刺之血出多。色不变而烦悗者。刺络而虚经。虚经之属于阴者。阴脱。故烦悗。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hL6p9efDMdK', 4, '{"title":"第20300474条・血络论第三十九","description":"<p>9、阴阳相得而合为痹者。此为内溢于经。外注于络。如是者。阴阳俱有余。虽多出血而弗能虚也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300474,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '9、阴阳相得而合为痹者。此为内溢于经。外注于络。如是者。阴阳俱有余。虽多出血而弗能虚也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('L83h2EjQFSn', 4, '{"title":"第20300475条・血络论第三十九","description":"<p>10、黄帝曰。相之奈何。岐伯曰。血脉者。盛坚横以赤。上下无常处。小者如针。大者如筋。则而泻之万全也。故无失数矣。失数而反。各如其度。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300475,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '10、黄帝曰。相之奈何。岐伯曰。血脉者。盛坚横以赤。上下无常处。小者如针。大者如筋。则而泻之万全也。故无失数矣。失数而反。各如其度。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MM8dM6ZgWRB', 4, '{"title":"第20300476条・血络论第三十九","description":"<p>11、黄帝曰。针入而肉著者。何也。岐伯曰。热气因于针。则针热。热则内着于针。故坚焉。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300476,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '11、黄帝曰。针入而肉著者。何也。岐伯曰。热气因于针。则针热。热则内着于针。故坚焉。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'ywfj9DjwNfi');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eNsVuPicmWw', 4, '{"title":"第20300477条・阴阳清浊第四十","description":"<p>1、黄帝曰。余闻十二经脉。以应十二经水者。其五色各异。清浊不同。人之血气若一。应之奈何。岐伯曰。人之血气。苟能若一。则天下为一矣。恶有乱者乎。黄帝曰。余问一人。非问天下之众。岐伯曰。夫一人者。亦有乱气。天下之象。亦有乱人。其合为一耳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300477,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。余闻十二经脉。以应十二经水者。其五色各异。清浊不同。人之血气若一。应之奈何。岐伯曰。人之血气。苟能若一。则天下为一矣。恶有乱者乎。黄帝曰。余问一人。非问天下之众。岐伯曰。夫一人者。亦有乱气。天下之象。亦有乱人。其合为一耳。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RJyboJtVGs3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3oGBdOXhU0a', 4, '{"title":"第20300478条・阴阳清浊第四十","description":"<p>2、黄帝曰。愿闻人气之清浊。岐伯曰。受谷者浊。受气者清。清者注阴。浊者注阳。浊而清者。上出于咽。清而浊者。则下行。清浊相干。命曰乱气。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300478,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。愿闻人气之清浊。岐伯曰。受谷者浊。受气者清。清者注阴。浊者注阳。浊而清者。上出于咽。清而浊者。则下行。清浊相干。命曰乱气。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RJyboJtVGs3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TZsJ8y78aB4', 4, '{"title":"第20300479条・阴阳清浊第四十","description":"<p>3、黄帝曰。夫阴清而阳浊。浊者有清。清者有浊。清浊别之奈何。岐伯曰。气之大别。清者上注于肺。浊者下走于胃。胃之清气。上出于口。肺之浊气。下注于经。内积于海。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300479,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。夫阴清而阳浊。浊者有清。清者有浊。清浊别之奈何。岐伯曰。气之大别。清者上注于肺。浊者下走于胃。胃之清气。上出于口。肺之浊气。下注于经。内积于海。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RJyboJtVGs3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1C3j1g5tNCT', 4, '{"title":"第20300480条・阴阳清浊第四十","description":"<p>4、黄帝曰。诸阳皆浊。何阳浊甚乎。岐伯曰。手太阳独受阳之浊。手太阴独受阴之清。其清者上走空窍。其浊者下行诸经。诸阴皆清。足太阴独受其浊。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300480,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。诸阳皆浊。何阳浊甚乎。岐伯曰。手太阳独受阳之浊。手太阴独受阴之清。其清者上走空窍。其浊者下行诸经。诸阴皆清。足太阴独受其浊。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RJyboJtVGs3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('krFeadCSV5Y', 4, '{"title":"第20300481条・阴阳清浊第四十","description":"<p>5、黄帝曰。治之奈何。岐伯曰。清者其气滑。浊者其气涩。此气之常也。故刺阴者。深而留之。刺阳者。浅而疾之。清浊相干者。以数调之也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300481,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、黄帝曰。治之奈何。岐伯曰。清者其气滑。浊者其气涩。此气之常也。故刺阴者。深而留之。刺阳者。浅而疾之。清浊相干者。以数调之也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'RJyboJtVGs3');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ugs2lnDKZ2B', 4, '{"title":"第20300482条・阴阳系日月第四十一","description":"<p>1、黄帝曰。余闻天为阳。地为阴。日为阳。月为阴。其合之于人。奈何。岐伯曰。腰以上为天。腰以下为地。故天为阳。地为阴。故足之十二经脉。以应为十二月。月生于水。故在下者为阴。手之十指。以应十日。日主火。故在上者为阳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300482,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。余闻天为阳。地为阴。日为阳。月为阴。其合之于人。奈何。岐伯曰。腰以上为天。腰以下为地。故天为阳。地为阴。故足之十二经脉。以应为十二月。月生于水。故在下者为阴。手之十指。以应十日。日主火。故在上者为阳。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PPgfFCvQGPf', 4, '{"title":"第20300483条・阴阳系日月第四十一","description":"<p>2、黄帝曰。合之于脉。奈何。岐伯曰。寅者。正月之生阳也。主左足之少阳。未者。六月。主右足之少阳。卯者。二月。主左足之太阳。午者。五月。主右足之太阳。辰者。三月。主左足之阳明。巳者。四月。主右足之阳明。此两阳合于前。故曰阳明。申者。七月之生阴也。主右足之少阴。丑者。十二月。主左足之少阴。酉者。八月。主右足之太阴。子者。十一月。主左足之太阴。戌者。九月。主右足之厥阴。亥者。十月。主左足之厥阴。此两阴交尽。故曰厥阳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300483,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。合之于脉。奈何。岐伯曰。寅者。正月之生阳也。主左足之少阳。未者。六月。主右足之少阳。卯者。二月。主左足之太阳。午者。五月。主右足之太阳。辰者。三月。主左足之阳明。巳者。四月。主右足之阳明。此两阳合于前。故曰阳明。申者。七月之生阴也。主右足之少阴。丑者。十二月。主左足之少阴。酉者。八月。主右足之太阴。子者。十一月。主左足之太阴。戌者。九月。主右足之厥阴。亥者。十月。主左足之厥阴。此两阴交尽。故曰厥阳。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DEn6n5nXAUu', 4, '{"title":"第20300484条・阴阳系日月第四十一","description":"<p>3、甲主左手之少阳。己主右手之少阳。乙主左手之太阳。戊主右手之太阳。丙主左手之阳明。丁主右手之阳明。此两火并合。故为阳明。庚主右手之少阴。癸主左手之少阴。辛主右手之太阴。壬主左手之太阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300484,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、甲主左手之少阳。己主右手之少阳。乙主左手之太阳。戊主右手之太阳。丙主左手之阳明。丁主右手之阳明。此两火并合。故为阳明。庚主右手之少阴。癸主左手之少阴。辛主右手之太阴。壬主左手之太阴。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('54ieGWNGANn', 4, '{"title":"第20300485条・阴阳系日月第四十一","description":"<p>4、故足之阳者。阴中之少阳也。足之阴者。阴中之太阴也。手之阳者。阳中之太阳也。手之阴者。阳中之少阴也。腰以上者为阳。腰以下者为阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300485,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、故足之阳者。阴中之少阳也。足之阴者。阴中之太阴也。手之阳者。阳中之太阳也。手之阴者。阳中之少阴也。腰以上者为阳。腰以下者为阴。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qUsfpueq5TI', 4, '{"title":"第20300486条・阴阳系日月第四十一","description":"<p>5、其于五藏也。心为阳中之太阳。肺为阴中之少阴。肝为阴中少阳。脾为阴中之至阴。肾为阴中之太阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300486,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、其于五藏也。心为阳中之太阳。肺为阴中之少阴。肝为阴中少阳。脾为阴中之至阴。肾为阴中之太阴。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GvJu61M4flE', 4, '{"title":"第20300487条・阴阳系日月第四十一","description":"<p>6、黄帝曰。以治之奈何。岐伯曰。正月二月三月。人气在左。无刺左足之阳。四月五月六月。人气在右。无刺右足之阳。七月八月九月。人气在右。无刺右足之阴。十月十一月十二月。人气在左。无刺左足之阴。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300487,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、黄帝曰。以治之奈何。岐伯曰。正月二月三月。人气在左。无刺左足之阳。四月五月六月。人气在右。无刺右足之阳。七月八月九月。人气在右。无刺右足之阴。十月十一月十二月。人气在左。无刺左足之阴。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('32wxwi02eCW', 4, '{"title":"第20300488条・阴阳系日月第四十一","description":"<p>7、黄帝曰。五行以东方为甲乙木主春。春者。苍色。主肝。肝者。足厥阴也。今乃以甲为左手之少阳。不合于数。何也。岐伯曰。此天地之阴阳也。非四时五行之以次行也。且夫阴阳者。有名而无形。故数之可十。离之可百。散之可千。推之可万。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300488,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、黄帝曰。五行以东方为甲乙木主春。春者。苍色。主肝。肝者。足厥阴也。今乃以甲为左手之少阳。不合于数。何也。岐伯曰。此天地之阴阳也。非四时五行之以次行也。且夫阴阳者。有名而无形。故数之可十。离之可百。散之可千。推之可万。此之谓也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '05J1DY03Sbt');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('f20gVaaohk9', 4, '{"title":"第20300489条・病传第四十二","description":"<p>1、黄帝曰。余受九针于夫子。而私览于诸方。或有导引行气。乔摩。灸。熨。刺。焫。饮药之一者。可独守耶。将尽行之乎。岐伯曰。诸方者。众人之方也。非一人之所尽行也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300489,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。余受九针于夫子。而私览于诸方。或有导引行气。乔摩。灸。熨。刺。焫。饮药之一者。可独守耶。将尽行之乎。岐伯曰。诸方者。众人之方也。非一人之所尽行也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k3INHpjaM02', 4, '{"title":"第20300490条・病传第四十二","description":"<p>2、黄帝曰。此乃所谓守一勿失。万物毕者也。今余已闻阴阳之要。虚实之理。倾移之过。可治之属。愿闻病之变化。淫传绝败而不可治者。可得闻乎。岐伯曰。要乎哉问也。昭乎其如日醒。窘乎其如夜瞑。能被而服之。神与俱成。毕将服之。神自得之。生神之理。可着于竹帛。不可传于子孙。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300490,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。此乃所谓守一勿失。万物毕者也。今余已闻阴阳之要。虚实之理。倾移之过。可治之属。愿闻病之变化。淫传绝败而不可治者。可得闻乎。岐伯曰。要乎哉问也。昭乎其如日醒。窘乎其如夜瞑。能被而服之。神与俱成。毕将服之。神自得之。生神之理。可着于竹帛。不可传于子孙。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qgk5pS6fcVy', 4, '{"title":"第20300491条・病传第四十二","description":"<p>3、黄帝曰。何谓日醒。岐伯曰。明于阴阳。如惑之解。如醉之醒。黄帝曰。何谓夜瞑。岐伯曰。瘖乎其无声。漠乎其无形。折毛发理。正气横倾。淫邪泮衍。血脉传溜。大气入藏。腹痛下淫。可以致死。不可以致生。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300491,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。何谓日醒。岐伯曰。明于阴阳。如惑之解。如醉之醒。黄帝曰。何谓夜瞑。岐伯曰。瘖乎其无声。漠乎其无形。折毛发理。正气横倾。淫邪泮衍。血脉传溜。大气入藏。腹痛下淫。可以致死。不可以致生。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LMLO7kFm1li', 4, '{"title":"第20300492条・病传第四十二","description":"<p>4、黄帝曰。大气入藏。奈何。岐伯曰。病先发于心。一日而之肺。三日而之肝。五日而之脾。三日不已。死。冬夜半。夏日中。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300492,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。大气入藏。奈何。岐伯曰。病先发于心。一日而之肺。三日而之肝。五日而之脾。三日不已。死。冬夜半。夏日中。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9WXPV7nXeE2', 4, '{"title":"第20300493条・病传第四十二","description":"<p>5、病先发于肺。三日而之肝。一日而之脾。五日而之胃。十日不已。死。冬日入。夏日出。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300493,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、病先发于肺。三日而之肝。一日而之脾。五日而之胃。十日不已。死。冬日入。夏日出。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k0p3DFtol6e', 4, '{"title":"第20300494条・病传第四十二","description":"<p>6、病先发于肝。三日而之脾。五日而之胃。三日而之肾。三日不已。死。冬日入。夏蚤食。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300494,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、病先发于肝。三日而之脾。五日而之胃。三日而之肾。三日不已。死。冬日入。夏蚤食。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nCc0zTjb7yQ', 4, '{"title":"第20300495条・病传第四十二","description":"<p>7、病先发于脾。一日而之胃。二日而之肾。三日而之膂膀胱。十日不已。死。冬人定。夏晏食。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300495,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、病先发于脾。一日而之胃。二日而之肾。三日而之膂膀胱。十日不已。死。冬人定。夏晏食。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RPGB81T41Qa', 4, '{"title":"第20300496条・病传第四十二","description":"<p>8、病先发于胃。五日而之肾。三日而之膂膀胱。五日而上之心。二日不已。死。冬夜半。夏日昳。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300496,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '8、病先发于胃。五日而之肾。三日而之膂膀胱。五日而上之心。二日不已。死。冬夜半。夏日昳。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4p6GFEIUGdG', 4, '{"title":"第20300497条・病传第四十二","description":"<p>9、病先发于肾。三日而之膂膀胱。三日而上之心。三日而之小肠。三日不已。死。冬大晨。夏晏晡。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300497,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '9、病先发于肾。三日而之膂膀胱。三日而上之心。三日而之小肠。三日不已。死。冬大晨。夏晏晡。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dMh0nX1OKmg', 4, '{"title":"第20300498条・病传第四十二","description":"<p>10、病先发于膀胱。五日而之肾。一日而之小肠。一日而之心。二日不已。死。冬鸡鸣。夏下晡。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300498,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '10、病先发于膀胱。五日而之肾。一日而之小肠。一日而之心。二日不已。死。冬鸡鸣。夏下晡。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nnq9UOQrqWs', 4, '{"title":"第20300499条・病传第四十二","description":"<p>11、诸病以次相传。如是者。皆有死期。不可刺也。间一藏及二。三。四藏者。乃可刺也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300499,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '11、诸病以次相传。如是者。皆有死期。不可刺也。间一藏及二。三。四藏者。乃可刺也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'AgLN6ztPPMp');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GgQ0sFagrAL', 4, '{"title":"第20300500条・淫邪发梦第四十三","description":"<p>1、黄帝曰。愿闻淫邪泮衍。奈何。岐伯曰。正邪从外袭内。而未有定舍。反淫于藏。不得定处。与营卫俱行。而与魂魄飞扬。使人卧不得安而喜梦。气淫于府。则有余于外。不足于内。气淫于藏。则有余于内。不足于外。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300500,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。愿闻淫邪泮衍。奈何。岐伯曰。正邪从外袭内。而未有定舍。反淫于藏。不得定处。与营卫俱行。而与魂魄飞扬。使人卧不得安而喜梦。气淫于府。则有余于外。不足于内。气淫于藏。则有余于内。不足于外。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4cgUVxMd968');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q4xbZjatiij', 4, '{"title":"第20300501条・淫邪发梦第四十三","description":"<p>2、黄帝曰。有余不足。有形乎。岐伯曰。阴气盛。则梦涉大水而恐惧。阳气盛。则梦大火而燔焫。阴阳俱盛。则梦相杀。上盛则梦飞。下盛则梦堕。甚饥则梦取。甚饱则梦予。肝气盛。则梦怒。肺气盛。则梦恐惧。哭泣。飞扬。心气盛。则梦善笑恐畏。脾气盛。则梦歌。身体重不举。肾气盛。则梦腰脊两解不属。凡此十二盛者。至而泻之。立已。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300501,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。有余不足。有形乎。岐伯曰。阴气盛。则梦涉大水而恐惧。阳气盛。则梦大火而燔焫。阴阳俱盛。则梦相杀。上盛则梦飞。下盛则梦堕。甚饥则梦取。甚饱则梦予。肝气盛。则梦怒。肺气盛。则梦恐惧。哭泣。飞扬。心气盛。则梦善笑恐畏。脾气盛。则梦歌。身体重不举。肾气盛。则梦腰脊两解不属。凡此十二盛者。至而泻之。立已。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4cgUVxMd968');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PW0NRL3nAiZ', 4, '{"title":"第20300502条・淫邪发梦第四十三","description":"<p>3、厥气客于心。则梦见丘山烟火。客于肺。则梦飞扬。见金铁之奇物。客于肝。则梦山林树木。客于脾。则梦见丘陵大泽。坏屋风雨。客于肾。则梦临渊。没居水中。客于膀胱。则梦游行。客于胃。则梦饮食。客于大肠。则梦田野。客于小肠。则梦聚邑冲衢。客于胆。则梦斗讼自刳。客于阴器。则梦接内。客于项。则梦斩首。客于胫。则梦行走而不能前。及居深地窌苑中。客于股肱。则梦礼节拜起。客于胞䐈。则梦溲便。凡此十五不足者。至而补之立已也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300502,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、厥气客于心。则梦见丘山烟火。客于肺。则梦飞扬。见金铁之奇物。客于肝。则梦山林树木。客于脾。则梦见丘陵大泽。坏屋风雨。客于肾。则梦临渊。没居水中。客于膀胱。则梦游行。客于胃。则梦饮食。客于大肠。则梦田野。客于小肠。则梦聚邑冲衢。客于胆。则梦斗讼自刳。客于阴器。则梦接内。客于项。则梦斩首。客于胫。则梦行走而不能前。及居深地窌苑中。客于股肱。则梦礼节拜起。客于胞䐈。则梦溲便。凡此十五不足者。至而补之立已也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', '4cgUVxMd968');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cL7YvXKlngS', 4, '{"title":"第20300503条・顺气一日分为四时第四十四","description":"<p>1、黄帝曰。夫百病之所始生者。必起于燥温寒暑风雨阴阳喜怒饮食居处。气合而有形。得藏而有名。余知其然也。夫百病者。多以旦慧昼安。夕加夜甚。何也。岐伯曰。四时之气使然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300503,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、黄帝曰。夫百病之所始生者。必起于燥温寒暑风雨阴阳喜怒饮食居处。气合而有形。得藏而有名。余知其然也。夫百病者。多以旦慧昼安。夕加夜甚。何也。岐伯曰。四时之气使然。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E7mJmzF7KEm', 4, '{"title":"第20300504条・顺气一日分为四时第四十四","description":"<p>2、黄帝曰。愿闻四时之气。岐伯曰。春生。夏长。秋收。冬藏。是气之常也。人亦应之。以一日分为四时。朝则为春。日中为夏。日入为秋。夜半为冬。朝则人气始生。病气衰。故旦慧。日中人气长。长则胜邪。故安。夕则人气始衰。邪气始生。故加。夜半人气入藏。邪气独居于身。故甚也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300504,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。愿闻四时之气。岐伯曰。春生。夏长。秋收。冬藏。是气之常也。人亦应之。以一日分为四时。朝则为春。日中为夏。日入为秋。夜半为冬。朝则人气始生。病气衰。故旦慧。日中人气长。长则胜邪。故安。夕则人气始衰。邪气始生。故加。夜半人气入藏。邪气独居于身。故甚也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('o0i284vJRvN', 4, '{"title":"第20300505条・顺气一日分为四时第四十四","description":"<p>3、黄帝曰。有时有反者何也。岐伯曰。是不应四时之气。藏独主其病者。是必以藏气之所不胜时者甚。以其所胜时者起也。黄帝曰。治之奈何。岐伯曰。顺天之时。而病可与期。顺者为工。逆者为粗。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300505,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。有时有反者何也。岐伯曰。是不应四时之气。藏独主其病者。是必以藏气之所不胜时者甚。以其所胜时者起也。黄帝曰。治之奈何。岐伯曰。顺天之时。而病可与期。顺者为工。逆者为粗。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hG793R1GH3g', 4, '{"title":"第20300506条・顺气一日分为四时第四十四","description":"<p>4、黄帝曰。善。余闻刺有五变。以主五输。愿闻其数。岐伯曰。人有五藏。五藏有五变。五变有五输。故五五二十五输。以应五时。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300506,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。善。余闻刺有五变。以主五输。愿闻其数。岐伯曰。人有五藏。五藏有五变。五变有五输。故五五二十五输。以应五时。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Kb8rMRnrONA', 4, '{"title":"第20300507条・顺气一日分为四时第四十四","description":"<p>5、黄帝曰。愿闻五变。岐伯曰。肝为牡藏。其色青。其时春。其音角。其味酸。其日甲乙。心为牡藏。其色赤。其时夏。其日丙丁。其音征。其味苦。脾为牝藏。其色黄。其时长夏。其日戊己。其音宫。其味甘。肺为牝藏。其色白。其音商。其时征。其日庚辛。其味辛。肾为牝藏。其色黑。其时冬。其日壬癸。其音羽。其味咸。是为五变。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300507,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '5、黄帝曰。愿闻五变。岐伯曰。肝为牡藏。其色青。其时春。其音角。其味酸。其日甲乙。心为牡藏。其色赤。其时夏。其日丙丁。其音征。其味苦。脾为牝藏。其色黄。其时长夏。其日戊己。其音宫。其味甘。肺为牝藏。其色白。其音商。其时征。其日庚辛。其味辛。肾为牝藏。其色黑。其时冬。其日壬癸。其音羽。其味咸。是为五变。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fRPRC507hnm', 4, '{"title":"第20300508条・顺气一日分为四时第四十四","description":"<p>6、黄帝曰。以主五输奈何。藏主冬。冬刺井。色主春。春刺荥。时主夏。夏刺输。音主长夏。长夏刺经。味主秋。秋刺合。是谓五变。以主五输。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300508,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '6、黄帝曰。以主五输奈何。藏主冬。冬刺井。色主春。春刺荥。时主夏。夏刺输。音主长夏。长夏刺经。味主秋。秋刺合。是谓五变。以主五输。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QealeEeJimS', 4, '{"title":"第20300509条・顺气一日分为四时第四十四","description":"<p>7、黄帝曰。诸原安和。以致五输。岐伯曰。原独不应五时。以经合之。以应其数。故六六三十六输。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300509,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '7、黄帝曰。诸原安和。以致五输。岐伯曰。原独不应五时。以经合之。以应其数。故六六三十六输。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3SuOKufD7jB', 4, '{"title":"第20300510条・顺气一日分为四时第四十四","description":"<p>8、黄帝曰。何谓藏主冬。时主夏。音主长夏。味主秋。色主春。愿闻其故。岐伯曰。病在藏者。取之井。病变于色者。取之荥。病时间时甚者。取之输。病变于音者。取之经。经满而血者。病在胃。及以饮食不节得病者。取之于合。故命曰味主合。是谓五变也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300510,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '8、黄帝曰。何谓藏主冬。时主夏。音主长夏。味主秋。色主春。愿闻其故。岐伯曰。病在藏者。取之井。病变于色者。取之荥。病时间时甚者。取之输。病变于音者。取之经。经满而血者。病在胃。及以饮食不节得病者。取之于合。故命曰味主合。是谓五变也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'DYxf7kx3NPY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vtUApgfS8cB', 4, '{"title":"第20300511条・外揣第四十五","description":"<p>1、余闻九针九篇。余亲受其调。颇得其意。夫九针者。始于一而终于九。然未得其要道也。夫九针者。小之则无内。大之则无外。深不可为下。高不可为盖。恍惚无窍。流溢无极。畲知其合于天道人事四时之变也。然余愿杂之毫毛。浑束为一。可乎。岐伯曰。明乎哉问也。非独针道焉。夫治国亦然。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300511,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '1、余闻九针九篇。余亲受其调。颇得其意。夫九针者。始于一而终于九。然未得其要道也。夫九针者。小之则无内。大之则无外。深不可为下。高不可为盖。恍惚无窍。流溢无极。畲知其合于天道人事四时之变也。然余愿杂之毫毛。浑束为一。可乎。岐伯曰。明乎哉问也。非独针道焉。夫治国亦然。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'mfeQeHbcrUn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IjNNP1bBTzU', 4, '{"title":"第20300512条・外揣第四十五","description":"<p>2、黄帝曰。余愿闻针道。非国事也。岐伯曰。夫治国者。夫惟道焉。非道。何可小大深浅。杂合而为一乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300512,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2、黄帝曰。余愿闻针道。非国事也。岐伯曰。夫治国者。夫惟道焉。非道。何可小大深浅。杂合而为一乎。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'mfeQeHbcrUn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b429lpL5Sds', 4, '{"title":"第20300513条・外揣第四十五","description":"<p>3、黄帝曰。愿卒闻之。岐伯曰。日与月焉。水与镜焉。鼓与响焉。夫日月之明。不失其影。水镜之察。不失其形。鼓响之应。不后其声。动摇则应和。尽得其情。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300513,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '3、黄帝曰。愿卒闻之。岐伯曰。日与月焉。水与镜焉。鼓与响焉。夫日月之明。不失其影。水镜之察。不失其形。鼓响之应。不后其声。动摇则应和。尽得其情。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'mfeQeHbcrUn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1JeQMAtWTB7', 4, '{"title":"第20300514条・外揣第四十五","description":"<p>4、黄帝曰。窘乎哉。昭昭之明不可蔽。其不可蔽。不失阴阳也。合而察之。切而验之。见而得之。若清水明镜之不失其形也。五音不彰。五色不明。五藏波荡。若是则内外相袭。若鼓之应桴。响之应声。影之似形。故远者。司外揣内。近者。司内揣外。是谓阴阳之极。天地之盖。请藏之灵兰之室。弗敢使泄也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300514,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '2024-09-26T13:54:47.000Z', '4、黄帝曰。窘乎哉。昭昭之明不可蔽。其不可蔽。不失阴阳也。合而察之。切而验之。见而得之。若清水明镜之不失其形也。五音不彰。五色不明。五藏波荡。若是则内外相袭。若鼓之应桴。响之应声。影之似形。故远者。司外揣内。近者。司内揣外。是谓阴阳之极。天地之盖。请藏之灵兰之室。弗敢使泄也。', '2024-09-26T13:54:47.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'mfeQeHbcrUn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O2M6WPcAzle', 4, '{"title":"第20300515条・五变第四十六","description":"<p>1、黄帝问于少俞曰。余闻百疾之始期也。必生于风雨寒暑。循毫毛而入腠理。或复还。或留止。或为风肿汗出。或为消瘅。或为寒热。或为留痹。或为积聚。奇邪淫溢。不可胜数。愿闻其故。夫同时得病。或病此。或病彼。意者天之为人生风乎。何其异也。少俞曰。夫天之生风者。非以私百姓也。其行公平正直。犯者得之。避者得无殆。非求人而人自犯之。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300515,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '1、黄帝问于少俞曰。余闻百疾之始期也。必生于风雨寒暑。循毫毛而入腠理。或复还。或留止。或为风肿汗出。或为消瘅。或为寒热。或为留痹。或为积聚。奇邪淫溢。不可胜数。愿闻其故。夫同时得病。或病此。或病彼。意者天之为人生风乎。何其异也。少俞曰。夫天之生风者。非以私百姓也。其行公平正直。犯者得之。避者得无殆。非求人而人自犯之。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k6QH1eUAF6L', 4, '{"title":"第20300516条・五变第四十六","description":"<p>2、黄帝曰。一时遇风。同时得病。其病各异。愿闻其故。少俞曰。善乎其问。请论以比匠人。匠人磨斧斤。砺刀削断材木。木之阴阳。尚有坚脆。坚者不入。脆者皮弛。至其交节。而缺斤斧焉。夫一木之中。坚脆不同。坚者则刚。脆者易伤。况其材木之不同。皮之厚薄。汁之多少。而各异耶。夫木之蚤花先生叶者。遇春霜烈风。则花落而叶萎。久曝大旱。则脆木薄皮者。枝条汁少而叶萎。久阴淫雨。则薄皮多汁者。皮漉而浅。卒风暴起。则刚脆之木。根摇而叶落。凡此五者。各有所伤。况于人乎。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300516,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2、黄帝曰。一时遇风。同时得病。其病各异。愿闻其故。少俞曰。善乎其问。请论以比匠人。匠人磨斧斤。砺刀削断材木。木之阴阳。尚有坚脆。坚者不入。脆者皮弛。至其交节。而缺斤斧焉。夫一木之中。坚脆不同。坚者则刚。脆者易伤。况其材木之不同。皮之厚薄。汁之多少。而各异耶。夫木之蚤花先生叶者。遇春霜烈风。则花落而叶萎。久曝大旱。则脆木薄皮者。枝条汁少而叶萎。久阴淫雨。则薄皮多汁者。皮漉而浅。卒风暴起。则刚脆之木。根摇而叶落。凡此五者。各有所伤。况于人乎。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oVDTuNNkekz', 4, '{"title":"第20300517条・五变第四十六","description":"<p>3、黄帝曰。以人应木。奈何。少俞答曰。木之所伤也。皆伤其枝。枝之刚脆而坚。未成伤也。人之有常病也。亦因其骨节皮肤腠理之不坚固者。邪之所舍也。故常为病也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300517,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '3、黄帝曰。以人应木。奈何。少俞答曰。木之所伤也。皆伤其枝。枝之刚脆而坚。未成伤也。人之有常病也。亦因其骨节皮肤腠理之不坚固者。邪之所舍也。故常为病也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qPkFnS75lPN', 4, '{"title":"第20300518条・五变第四十六","description":"<p>4、黄帝曰。人之善病风厥漉汗者。何以候之。少俞答曰。内不坚。腠理疏。则善病风。黄帝曰。何以候肉之不坚也。少俞答曰。腘肉不坚。而无分理。理者粗理。粗理而皮不致者。腠理疏。此言其浑然者。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300518,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '4、黄帝曰。人之善病风厥漉汗者。何以候之。少俞答曰。内不坚。腠理疏。则善病风。黄帝曰。何以候肉之不坚也。少俞答曰。腘肉不坚。而无分理。理者粗理。粗理而皮不致者。腠理疏。此言其浑然者。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('igDgXDZdIGQ', 4, '{"title":"第20300519条・五变第四十六","description":"<p>5、黄帝曰。人之善病消瘅者。何以候之。少俞答曰。五藏皆柔弱者。善病消瘅。黄帝曰。何以知五藏之柔弱也。少俞答曰。夫柔弱者。必有刚强。刚强多怒。柔者易伤也。黄帝曰。何以候柔弱之与刚强。少俞答曰。此人薄皮肤。而目坚固以深者。长冲直肠。其心刚。刚则多怒。怒则气上逆。胸中蓄积。血气逆留。髋皮充肌。血脉不行。转而为热。热则消肌肤。故为消瘅。此言其人暴刚而肌肉弱者也。</p>","content_format":"html","_microfeed":{"bookId":"ghBqURJwurj","receiptNo":20300519,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '2024-09-26T13:54:48.000Z', '5、黄帝曰。人之善病消瘅者。何以候之。少俞答曰。五藏皆柔弱者。善病消瘅。黄帝曰。何以知五藏之柔弱也。少俞答曰。夫柔弱者。必有刚强。刚强多怒。柔者易伤也。黄帝曰。何以候柔弱之与刚强。少俞答曰。此人薄皮肤。而目坚固以深者。长冲直肠。其心刚。刚则多怒。怒则气上逆。胸中蓄积。血气逆留。髋皮充肌。血脉不行。转而为热。热则消肌肤。故为消瘅。此言其人暴刚而肌肉弱者也。', '2024-09-26T13:54:48.000Z', 1, NULL, 'ghBqURJwurj', 'section', 'cvZKnvxZCLH');
